(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-dctext-scheduled-attention-masking-f-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-1\">一 · 开场：一个排版请求在在线服务里的真实路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-2\">二 · 旧方案的三条技术路线与其代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-3\">三 · 为什么非改不可：平方级代价与质量天花板的夹击</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-4\">四 · 旧方案在采样轨迹上的结构性缺陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-5\">五 · 工程视角下的失败模式与批调度约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-6\">六 · 掩码调度的边界：平方级显存、解析上游与批对齐代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-7\">七 · 请求形态：从版面描述到注意力序列长度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-8\">八 · 并发与批大小：平方项如何反过来限制负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-9\">九 · SLO 与长尾：步数不变，时延结构变了</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-10\">十 · 负载塑造方案：分桶、预计算与稀疏度预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-11\">十一 · 方案反过来限制负载：可接受请求域的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-12\">十二 · 测量口径的落地：从请求日志到容量规划</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-13\">十三 · 负载形态如何反向约束掩码调度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-14\">十四 · 掩码注意力的算子形态与数据流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-15\">十五 · 数据类型选择：FP16/BF16、FP8 与 NVFP4 在掩码注意力中的分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-16\">十六 · 累加精度与误差传播：从 logits 到字形</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-17\">十七 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA 对掩码注意力的意义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-18\">十八 · 稀疏索引的访存代价与 kernel 选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-19\">十九 · 块对角掩码的算子边界：稀疏索引、精度路径与显存平方项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-20\">二十 · 显存账本的三层结构：权重、激活、掩码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-21\">二十一 · 分页与复用：把掩码从平方级拉回线性级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-22\">二十二 · 压缩：布尔掩码不量化，但索引可以压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-23\">二十三 · 卸载与容量档位：HBM3e 怎么算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-24\">二十四 · 可复算的显存预算与调度耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-25\">二十五 · 掩码矩阵的显存账本与批调度边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-26\">二十六 · 掩码构造从采样循环里剥离：预计算与分桶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-27\">二十七 · 连续批处理与 chunked prefill 在扩散采样里的变形</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-28\">二十八 · 优先级、抢占与尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-29\">二十九 · 分离式预填/解码的映射：版面解析与采样分离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-30\">三十 · 时延与吞吐的取舍：掩码稀疏度作为调节旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-31\">三十一 · 监控项与调度器的可观测性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-32\">三十二 · 从单卡掩码到多卡切分：DCText 的并行边界在哪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-33\">三十三 · NVLink 5 与 NVSwitch：域内带宽决定了哪种切分可行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-34\">三十四 · All-to-All 与 All-Reduce 的代价结构不同</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-35\">三十五 · NIXL 传输：把掩码与潜变量放在正确的存储层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-36\">三十六 · 通信成为瓶颈的三个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-37\">三十七 · 并行拓扑与掩码调度的联动设计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-38\">三十八 · 精度塌陷：从字形断裂到跨块语义漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-39\">三十九 · OOM 与批抖动：平方级掩码矩阵的真实代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-40\">四十 · 尾延迟：掩码构造与采样循环的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-41\">四十一 · 静默降级：没有报错的错误输出</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-42\">四十二 · 回滚路径：把调度器做成可旁路的一层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-43\">四十三 · 诊断顺序：从上游解析到下游内核</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-44\">四十四 · 掩码调度的失效边界与端到端诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-45\">四十五 · 口径先行：这份材料能读出什么、不能读出什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-46\">四十六 · 硬件档位与 batch：材料空白处的推断边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-47\">四十七 · 数字怎么读：四类不可比提升</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-48\">四十八 · 质量侧代理指标：稀疏度与泄漏比例怎么当数用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-49\">四十九 · 消融维度的口径：没有数值时如何设计自己的对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-50\">五十 · 容量规划：把缺失的数字换成可执行的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-51\">五十一 · 迁移到非 DiT 主干：掩码挂载点决定改造量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-52\">五十二 · 迁移到别的生成领域：文本块假设是否成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-53\">五十三 · 与其他推理加速手段叠加时的相互作用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-54\">五十四 · 规模上限：平方项与解析精度两条硬边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-55\">五十五 · 不适用的场景与判断清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dctext-scheduled-attention-masking-f-2025-sec-56\">五十六 · 迁移边界：掩码调度在哪些模型与场景上会失效</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:584px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 584.1 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">版面解析得到各文本块的包围盒与阅读顺序，映射到潜变量网格坐标。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">文本编码器输出各块 token 嵌入，与图像条件拼接为注意力序列。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按当前采样步计算掩码温度，生成块对角为主、块间泄漏随步数衰减的注意力掩…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">DiT 前向在自注意力层施加掩码，文本 token 仅聚合所属块潜变量。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">后期步掩码收紧至块内，逐块锐化笔画后由 VAE 解码输出整图。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-1\">一 · 开场：一个排版请求在在线服务里的真实路径</h3>\n<p>设想一个电商海报生成接口：运营侧提交一段 JSON，包含主标题、副标题、三行卖点文案与角标价格，版面解析模块把它们映射成潜变量网格上的若干包围盒，随后进入扩散或流匹配采样循环。请求进来时并发并不高，单图端到端 SLO 卡在数百毫秒量级，GPU 上跑的是 DiT 主干加 VAE 解码。工程团队最初的做法是把整段文本编码成一条条件序列，与图像潜变量拼接后送进自注意力层——这是视觉文本生成在 DCText 之前最主流、也最省事的推理栈形态：文本只是“更强的条件”，注意力在整幅潜变量上均匀铺开。</p>\n<p>这个做法在单行短标题上勉强能用，一旦进入多块、长字符的版面就开始出问题。字形 token 与背景 token 在同一注意力上下文里竞争权重：纹理丰富的背景（木纹、布料、渐变）分走的注意力份额直接体现为笔画断裂与字符粘连；多行多词场景下，不同文本块的 token 互相干扰，副标题的笔画会被主标题的注意力拖走。工程上第一反应是调大文本条件强度，但这会破坏整体构图一致性——光照、阴影、透视关系被文本条件压过去，整图看起来“贴”了一层字。</p>\n<p>这就是本部分要交代的问题现场：不是模型不会写字，而是推理栈里注意力的可见性没有按版面结构组织。DCText 的切入点正是把这件事从“条件强度”问题改写成“注意力可见性 + 采样步调度”问题，改动落在 DiT 自注意力算子与采样循环，不碰训练配方。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-2\">二 · 旧方案的三条技术路线与其代价结构</h3>\n<p>在 DCText 之前，推理栈处理视觉文本的主流做法可以归成三条路线，每条都有自己的代价结构，且都不是为“多块版面”设计的。</p>\n<ul>\n<li><strong>全局条件注入</strong>：文本编码器输出一条序列，与潜变量序列拼接，自注意力不做任何区域约束。优点是零改造、可直接复用现有 DiT 推理内核；代价是注意力权重被背景稀释，序列长度随字符数线性增长，而注意力计算量随总序列长度平方增长。一个含四块文本、总字符数较长的海报请求，其注意力序列长度远大于纯图请求，单步前向的算力与激活显存同步抬升。</li>\n<li><strong>区域条件加权</strong>：在 cross-attention 或拼接位置上给文本 token 加权重，试图用标量强度压过背景。优点是实现简单；代价是权重与构图一致性直接冲突——权重调高，字形锐了但全局光照崩；权重调低，构图稳了但笔画糊。这个矛盾没有调度维度可解，因为权重在整条采样轨迹上是常数。</li>\n<li><strong>后处理叠加</strong>：先出图，再用渲染或贴图把文字叠上去。优点是字形可控；代价是文字与图像的光照、材质、透视脱节，端到端时延还要多一段渲染管线，且版面解析误差会直接变成贴图错位。</li>\n</ul>\n<p>三条路线的共同短板是：注意力在整幅潜变量上均匀铺开，没有“按文本块划分可见性”的概念，也没有“按采样步调整可见性”的概念。前者导致块间干扰，后者导致构图稳定与字形锐化无法在一条轨迹上分阶段完成。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-3\">三 · 为什么非改不可：平方级代价与质量天花板的夹击</h3>\n<p>把问题量化一下。设注意力序列总长度为 <span>N</span>（图像潜变量 token 加文本 token），自注意力计算量按 <span>O(N²·d)</span> 增长，激活与中间矩阵显存同样按 <span>N²</span> 量级占位。多块长文本请求把 <span>N</span> 推高，单步时延与显存峰值同时上升；而批调度为了吞吐会把多个请求合并，序列按最长请求对齐，短请求被padding放大，掩码类结构的显存开销进一步被放大。这就是旧方案在在线服务里的吞吐天花板：不是 GPU 算不动，是序列膨胀把算力与显存一起吃掉了。</p>\n<div class=\"formula\">$$N = N_{\\text{latent}} + \\sum_{b=1}^{B} N_{\\text{text}}^{(b)},\\qquad \\text{Cost}_{\\text{attn}} \\propto N^2 \\cdot d$$</div>\n<p>质量侧的天花板同样硬。全局注意力下，字形 token 的注意力分布被背景 token 摊薄，笔画边缘的梯度信号弱；增大条件强度是在用构图一致性换字形锐度，二者在常数权重下不可兼得。更麻烦的是多块场景：不同文本块的 token 共享同一上下文，块间干扰随块数增加而累积，长文本与密集版面下表现为笔画断裂、字符粘连，且这种失败模式在上游版面解析误差存在时会被放大——包围盒错位直接传导为字形错位。</p>\n<p>一个具体例子：三行卖点文案加一个角标价格，四块文本、字符数中等。旧方案下，角标价格的字形常被主标题的注意力拖拽，价格数字的笔画末端出现粘连；运营侧看到的是“字写错了”，工程侧定位到的却是注意力权重分配问题。这类请求在并发上升时还会暴露另一个代价：掩码构造与稀疏索引若放在采样循环内做，CPU 侧成为瓶颈，GPU 等索引，单图端到端时延被非计算路径拉长。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-4\">四 · 旧方案在采样轨迹上的结构性缺陷</h3>\n<p>扩散与流匹配采样器的去噪轨迹有明确的阶段特征：早期步决定全局构图、光照与布局，后期步决定纹理与边缘细节。旧方案的注意力可见性在整条轨迹上是常数，这意味着它无法在早期步“放开”以稳定构图、在后期步“收紧”以锐化字形。条件强度是常数，注意力范围也是常数，两个常数无法同时服务两个阶段的目标。</p>\n<p>DCText 的核心判断正是把这两个阶段拆开：用采样步作为自变量调度注意力掩码的松紧。其掩码形式可写成块对角为主、块间泄漏随步数衰减的结构：</p>\n<div class=\"formula\">$$M_{ij}(t)=\\sigma\\!\\left(\\frac{\\lambda(t)}{\\tau}\\right)\\cdot\\mathbb{1}\\!\\left[\\mathrm{block}(i)=\\mathrm{block}(j)\\right]+\\left(1-\\sigma\\!\\left(\\frac{\\lambda(t)}{\\tau}\\right)\\right)\\cdot\\mathbb{1}\\!\\left[\\mathrm{block}(i)\\neq\\mathrm{block}(j)\\right],\\quad \\lambda(t)=\\lambda_{0}\\left(1-\\frac{t}{T}\\right)$$</div>\n<p>早期 <span>t</span> 小、<span>λ(t)</span> 大，块间泄漏比例高，注意力近似全局，构图与光照一致；随步数推进 <span>λ(t)</span> 衰减，掩码趋近块对角，文本 token 只能看到本块潜变量，笔画边缘获得更高注意力占比。注意这里采样步数不变，掩码调度只改变每步的可见性，因此端到端时延仍由 DiT 前向与 VAE 解码主导——这是它相对“加步数换质量”类方案在 SLO 上的关键优势。</p>\n<p>代价也很明确：掩码是布尔稀疏矩阵，规模随 <span>N²</span> 增长，块数与字符数增加时显存占用与稀疏索引开销同步上升；稀疏索引的访存模式会影响 FP8 或 NVFP4 注意力内核的实际吞吐，掩码本身不参与量化，但索引路径可能打断量化内核的连续访存。工程判断在这里很清楚：掩码构造必须与采样循环解耦、预计算，否则 CPU 侧索引构造会成为并发上升时的瓶颈。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-5\">五 · 工程视角下的失败模式与批调度约束</h3>\n<p>把旧方案换掉不是免费的。DCText 类方法的第一个失败模式是把掩码调度当作免费增益：掩码矩阵平方级显存开销在长文本多块场景会抵消质量收益，尤其在批合并后序列按最长请求对齐时，短请求的掩码矩阵被padding放大，显存峰值抬升直接压缩可批大小。批调度需要按块数与字符长度分桶，多块长文本请求宜单独成批，避免序列膨胀。</p>\n<p>第二个失败模式在上游：块划分依赖版面解析得到的包围盒，包围盒映射到潜变量网格的误差会直接造成字形错位。端到端失败模式发生在解析层而非注意力层，监控项应包含掩码稀疏度、块间泄漏比例、单步注意力时延与显存峰值，把解析误差与注意力竞争分开归因。第三个失败模式是混淆训练与推理：该方法不改训练配方，若期待它替代文本渲染专项训练会得到错误结论——它解决的是推理侧注意力可见性，不是字形表征能力本身。</p>\n<p>从容量规划角度，旧方案的吞吐天花板由 <span>N²</span> 决定，新方案的显存天花板同样由 <span>N²</span> 的掩码矩阵决定，两者在长文本版面下殊途同归；真正的工程收益取决于掩码稀疏实现能否落到块稀疏注意力内核上，以及能否与量化、批调度等部署手段叠加。这也是本部分留下的具体判断：问题现场不在“模型会不会写字”，而在推理栈有没有把版面结构编码进注意力的可见性，并用采样步把构图稳定与字形锐化分成两个可调度的阶段。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-6\">六 · 掩码调度的边界：平方级显存、解析上游与批对齐代价</h3>\n<p>把 DCText 放进在线服务现场，最先暴露的不是字形收益，而是掩码本身的代价结构。设注意力序列长度为 <span class=\"inline-math\">N</span>（文本 token 与潜变量 token 拼接后的总长）、文本块数为 <span class=\"inline-math\">B</span>，块对角掩码的非零元约为 <span class=\"inline-math\">∑<sub>b</sub> N<sub>b</sub><sup>2</sup></span>，但工程实现上若不做块稀疏内核而先物化稠密布尔矩阵，占用即为 <span class=\"inline-math\">N<sup>2</sup></span> 位或字节。更关键的是调度项：泄漏比例 <span class=\"inline-math\">σ(λ(t)/τ)</span> 在早期步接近 1，掩码近似全通，此时掩码不省任何算力；只有后期步趋近块对角，稀疏性才真正兑现。也就是说，质量收益集中在采样轨迹后段，而显存峰值出现在前段——两者在时间上错位，容量规划必须按峰值而非均值做。</p>\n<p>失效条件有三类，且都不在注意力层内部。其一是版面解析误差：包围盒映射到潜变量网格时的量化偏差会直接把块边界切进笔画，掩码收紧后文本 token 看不到被误划出去的那部分潜变量，表现为字形错位而非模糊，属于上游传导的硬失败。其二是跨块语义一致性：后期步块间泄漏趋零后，多行文本共享的光照、透视与材质线索被切断，密集版面下容易出现块与块之间风格漂移，材料未给出该退化的量化边界，只能定性判断其随块数增加而放大。其三是批对齐放大：多块长文本请求合并成批时序列按最长请求对齐，短请求的掩码矩阵与激活被无谓撑大，显存与索引开销按批内最大 <span class=\"inline-math\">N</span> 计，吞吐反而下降。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>主要代价</th><th>系统表现</th></tr></thead><tbody><tr><td>单块短文本</td><td>掩码构造与索引开销</td><td>收益有限，时延仍由 DiT 前向与 VAE 解码主导</td></tr><tr><td>多块密集版面</td><td>掩码矩阵平方级显存、稀疏访存</td><td>批大小被迫压缩，吞吐受显存峰值约束</td></tr><tr><td>解析失败请求</td><td>包围盒错位</td><td>字形错位，属端到端失败而非可调参退化</td></tr></tbody></table>\n<p>因此这套方案的适用边界是明确的：它把质量问题转化为注意力可见性问题，代价是把显存与吞吐押在块稀疏内核的落地程度上。若掩码只能以稠密布尔形式参与注意力计算，长文本多块场景的平方级开销会抵消字形收益；若稀疏索引的访存模式与 FP8/NVFP4 量化内核不匹配，量化路径的名义算力也兑现不了。工程判断应落在两处：掩码构造与采样循环解耦、按块数与字符长度分桶预计算，避免每步重算；以及把版面解析质量纳入 SLO 监控，因为它是这条链路上唯一无法在推理侧补救的失败源。</p>\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-7\">七 · 请求形态：从版面描述到注意力序列长度</h3>\n<p>在 DCText 的推理视角下，一个请求不是\"一句话\"，而是一张待生成图像的完整版面描述：若干文本块、每块的字符内容、阅读顺序，以及它们在画布上的位置关系。版面解析把这些信息映射成潜变量网格上的包围盒，文本编码器为每块产出 token 序列，与图像潜变量序列拼接成一条注意力序列。这条序列的长度决定了后续一切代价的基数：设潜变量网格被切成 N 个 patch token，第 k 个文本块产出 L_k 个 token，总序列长度为</p>\n<div class=\"formula\">$$S = N + \\sum_{k=1}^{K} L_k$$</div>\n<p>而掩码矩阵的规模是 S² 量级。这就是负载形态的第一条硬约束：请求的\"长度\"不是单一标量，而是由画布分辨率（决定 N）、文本块数 K、每块字符数（决定 L_k）三者共同张成的三元组。一个 K=2、每块十余字符的短标签请求，与一个 K=6、每块数十字符的海报请求，序列长度可能相差数倍，而掩码显存相差平方倍。工程上必须把 K 与 ΣL_k 作为分桶键，而不是只按 S 分桶——因为同样的 S，块数多意味着掩码中非对角块的稀疏索引更碎，块数少意味着掩码更接近稠密，两者的内核效率并不等价。</p>\n<p>可核查的测量口径：在请求入口记录 (N, K, L_1…L_K, S)，在注意力层记录掩码非零元个数与总元素数之比（稀疏度），以及每步掩码索引构建耗时。这三项足以把\"负载形态\"与\"系统代价\"对上账，而不必依赖任何未公开的端到端指标。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-8\">八 · 并发与批大小：平方项如何反过来限制负载</h3>\n<p>扩散采样没有自回归 KV cache，显存主要由潜变量序列与掩码矩阵占据，但这不意味着批处理是免费的。把 B 个请求合并成一批时，序列按批内最长请求对齐到 S_max，掩码矩阵按 B×S_max² 分配。设批内请求的块数分布不均，则短请求被迫携带大量填充 token，其掩码行整片为零却仍占显存。有效载荷率为</p>\n<div class=\"formula\">$$\\eta = \\frac{\\sum_{b=1}^{B} S_b}{B \\cdot S_{\\max}}$$</div>\n<p>当批内混入一个 K=6 的长海报请求时，S_max 被抬高，其余短请求的 η 迅速塌陷，显存峰值由最长请求决定而吞吐由平均值决定，二者背离。这就是\"方案反过来限制负载\"的具体机制：掩码的平方级开销使得连续批处理不能简单追求大 B，而必须按 (K, ΣL_k) 分桶，把长文本多块请求单独成批甚至单请求成批。代价是批内并行度下降、GPU 利用率在长尾请求上走低；收益是避免短请求被长请求的掩码显存拖垮。</p>\n<p>具体例子：一个电商横幅请求含标题、副标题、按钮文案三块文本，若与九个单行标签请求混批，S_max 由横幅决定，九个标签请求的掩码矩阵大部分是填充；分桶后横幅单独成批，标签请求以短序列高 η 成批，两批的显存峰值之和低于混批峰值。测量口径上应记录每批的 η、显存峰值、以及因分桶造成的批次数增量——分桶不是无代价的，批次数上升会稀释 kernel 启动摊销。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-9\">九 · SLO 与长尾：步数不变，时延结构变了</h3>\n<p>DCText 不改变采样步数 T，掩码调度只改变每步注意力的可见性，因此端到端时延仍由 DiT 前向与 VAE 解码主导。但\"主导\"不等于\"不变\"：每步注意力需按掩码屏蔽非法 query–key 对，稀疏索引的构建与访存会插入到采样循环的关键路径上。若掩码在每步现场构造，单步时延为</p>\n<div class=\"formula\">$$t_{\\text{step}} = t_{\\text{mask-build}}(t) + t_{\\text{attn}}(S, \\text{sparsity}) + t_{\\text{mlp}}$$</div>\n<p>其中 t_mask-build 与采样步 t 相关（温度 λ(t) 变化导致泄漏比例变化，稀疏结构随之改变），这意味着后期步掩码趋近块对角、非零元更少，但索引模式更规整；早期步泄漏大、掩码接近稠密，索引开销反而低。时延在轨迹上不是单调的。工程判断：把掩码构造与采样循环解耦预计算——版面解析后一次性生成各步的掩码结构（或至少生成块归属索引），采样循环内只做查表与屏蔽，把 t_mask-build 从关键路径挪到请求入口的预处理阶段。代价是预处理阶段的内存驻留（T 份掩码结构）与请求入口的排队时延，收益是采样循环内时延可预测。</p>\n<p>SLO 口径应以单图端到端时延的尾部分位数衡量，而非均值：长尾来自 K 大、ΣL_k 大的请求，它们的掩码显存与索引开销把单步时延推高，且更容易触发分桶导致的批内并行度下降。可核查的测量项包括：按 (K, ΣL_k) 分组的 P50/P99 端到端时延、每步掩码构造耗时占单步比例、以及分桶后批次数与 GPU 空闲间隙。这些量能把\"长尾\"从模糊感受变成可归因的账目。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-10\">十 · 负载塑造方案：分桶、预计算与稀疏度预算</h3>\n<p>负载形态对方案的塑造体现在三个可落地的设计选择上。其一是分桶策略：以 K 与 ΣL_k 为键而非仅以 S 为键，因为掩码的稀疏索引模式由块结构决定，同 S 不同 K 的请求在内核上表现不同。其二是掩码预计算：把 λ(t) 调度的掩码结构在请求入口生成，采样循环内只做布尔查表，避免每步重建索引。其三是稀疏度预算：为每类请求设定掩码非零元上限，超过上限则触发降级路径——例如减少块间泄漏的精细度、或把块划分粒度放粗，用质量换显存。降级路径必须与版面解析质量联动：包围盒误差本身就会造成字形错位，粗粒度块划分会放大这一误差，因此降级阈值应同时受解析置信度约束。</p>\n<p>具体例子：一个多语言包装盒请求，K=4、每块字符数不均（中文块短、英文块长），ΣL_k 偏大。若按 S 分桶会与一个 K=1 的长段落请求同批，但前者掩码是四块对角、后者是单块稠密，内核效率差异显著；按 (K, ΣL_k) 分桶后两者分开，各自走适合的稀疏内核。测量口径：记录每类桶的掩码稀疏度分布、内核实际吞吐（以每秒处理的注意力 query–key 对计）、以及降级触发次数。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-11\">十一 · 方案反过来限制负载：可接受请求域的边界</h3>\n<p>掩码平方级开销不只是\"代价\"，它直接划定了系统可接受的请求域。设显存预算为 M_mask，单请求掩码占用约为 c·S²（c 为每元素字节数，布尔结构可压缩但索引仍需存储），则单请求可承受的序列长度上界为</p>\n<div class=\"formula\">$$S_{\\max} \\approx \\sqrt{M_{\\text{mask}} / c}$$</div>\n<p>超过这个上界的请求要么被拒绝、要么被迫走降级路径、要么被拆分成多次生成再合成——而拆分合成会引入跨块语义一致性问题，恰恰是掩码收紧后材料未给出量化边界的退化风险所在。因此方案对负载的限制是双重的：显存上界限制了单请求的 K 与 ΣL_k 组合，而块划分依赖版面解析质量又限制了请求中版面描述的复杂度——包围盒越密、块间越近，解析误差传导为字形错位的概率越高。工程上应把这两个边界写进请求准入逻辑：超过 S_max 的请求在入口即分流，解析置信度低于阈值的请求走保守掩码（更早收紧、更少泄漏）而非激进调度。</p>\n<p>可核查的测量口径：准入拒绝率、降级路径触发率、以及按拒绝原因（显存上界 vs 解析置信度）分类的计数。这三项把\"方案限制负载\"从设计意图变成运行时可观测的事实，也是容量规划中把请求域与 GPU 显存档位对齐的依据。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-12\">十二 · 测量口径的落地：从请求日志到容量规划</h3>\n<p>把上述口径串成一条可执行的测量链：请求入口记录 (N, K, L_k, S, 解析置信度)，分桶后记录批内 η 与 S_max，采样循环内记录每步掩码构造耗时与稀疏度，注意力层记录内核吞吐与显存峰值，出口记录端到端时延与降级标记。这条链的关键在于把\"掩码\"作为一等公民度量——多数推理栈的监控只到 kernel 级时延与显存总量，而 DCText 的代价恰恰藏在掩码的平方项与稀疏索引里，不单独度量就无法归因。容量规划时，以分桶后的批次数与每桶的显存峰值为输入，反推给定 GPU 显存档位下可承载的并发请求数与 SLO 尾部时延；掩码预计算的内存驻留（T 份结构）应计入常驻开销而非临时缓冲，否则容量估算会系统性偏低。最终判断落在准入逻辑上：S_max 与解析置信度阈值是两个必须显式配置的参数，它们的取值直接决定系统是\"接受更多请求但尾部时延失控\"，还是\"拒绝长尾请求但时延可预测\"——这是负载形态与方案代价之间无法回避的取舍点。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-13\">十三 · 负载形态如何反向约束掩码调度</h3>\n<p>DCText 的请求不是“一张图”这么简单：一次请求携带版面描述与多段文本，文本块数与字符长度共同决定注意力序列长度，而掩码矩阵规模随该长度平方增长。设第 <em>r</em> 个请求有 <em>B<sub>r</sub></em> 个文本块、总 token 数 <em>N<sub>r</sub></em>，则单请求掩码显存约为 <em>c·N<sub>r</sub>²</em>（<em>c</em> 为布尔位与索引的每元素代价）。批内按最长请求对齐后，实际占用由 <em>max(N<sub>r</sub>)</em> 决定而非均值，因此多块长文本请求一旦与短请求合并成批，整批的掩码与激活显存被放大，吞吐收益被平方项吃掉。批调度必须按块数与字符长度分桶，长文本请求单独成批，这是该方案对负载的第一条硬约束。</p>\n<p>并发上升时，掩码构造与稀疏索引生成落在 CPU 侧，若与采样步循环串行，会形成每步的固定气泡。可行做法是把版面解析、包围盒到潜变量网格的映射、块对角索引预计算全部前移到请求准入阶段，与采样循环解耦；采样步内只做索引查表。此时端到端时延仍由 DiT 前向与 VAE 解码主导，掩码调度不改变步数，故 SLO 口径应取单图端到端时延的 P99，并把“掩码构造耗时”与“单步注意力时延”分开埋点，否则长尾会被误判为算子问题。长尾的真实来源通常是版面解析失败或包围盒越界——这类请求要么重解析、要么降级为全局注意力，二者都改变时延分布。</p>\n<p>方案反过来限制负载的边界很明确：块数多、字符长的版面在平方级显存下不经济，工程上应设块数上限与序列长度上限，超限请求退回无掩码路径或分块多次采样。掩码为布尔稀疏结构、不参与量化，注意力算子可沿用 FP8 或 NVFP4 路径，但稀疏索引的访存模式会削弱量化内核的连续访存优势，实际吞吐取决于索引布局是否与内核 tile 对齐。可核查的测量口径建议固定为四项：掩码稀疏度（非零块对角占比）、块间泄漏比例随步数曲线、单步注意力时延、显存峰值；四者需按块数分桶统计，否则均值会掩盖长文本桶的劣化。</p>\n<table class=\"mini\"><thead><tr><th>负载维度</th><th>对方案的作用</th><th>可核查口径</th></tr></thead><tbody><tr><td>块数 / 字符长度</td><td>决定掩码平方级显存与索引开销</td><td>按块数分桶的显存峰值</td></tr><tr><td>并发</td><td>掩码构造成为 CPU 侧瓶颈</td><td>掩码构造耗时 vs 单步注意力时延</td></tr><tr><td>批大小</td><td>按最长请求对齐放大占用</td><td>批内 max(N) 与均值之比</td></tr><tr><td>SLO / 长尾</td><td>解析失败触发降级路径</td><td>端到端时延 P99 与降级请求占比</td></tr></tbody></table>\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-14\">十四 · 掩码注意力的算子形态与数据流</h3>\n<p>DCText 的改动落在 DiT 自注意力层，因此本部分讨论的 kernel 不是通用 GEMM，而是“带块对角掩码的注意力”。一次前向的算子序列为：QKV 投影（GEMM）→ QK^T（GEMM）→ 掩码加法/屏蔽 → softmax（行归约）→ PV（GEMM）。掩码以布尔稀疏结构参与，其语义是把非法 query–key 对的 logits 置为 −∞，等价于在 softmax 前做一次按位选择。工程上这一步有两种落地方式：其一，把掩码展开成与注意力矩阵同形的加法偏置张量，走稠密 GEMM 后再做掩码加法；其二，在 QK^T 的输出上直接做块级跳过，只对可见块计算。前者实现简单但把平方级矩阵完整物化，后者依赖块稀疏内核，能把不可见块的 QK^T 与 PV 计算整体省掉。</p>\n<p>设序列长度为 N、块数为 B、每块 token 数为 n_b，则块对角掩码的可见对数为</p>\n<div class=\"formula\">$$C_{\\text{vis}}=\\sum_{b=1}^{B} n_b^{2},\\qquad C_{\\text{dense}}=N^{2},\\qquad \\rho=\\frac{C_{\\text{vis}}}{C_{\\text{dense}}}=\\frac{\\sum_b n_b^{2}}{N^{2}}$$</div>\n<p>ρ 即掩码稀疏度。当块大小均匀、B 较大时 ρ≈1/B，块稀疏内核的理论算力节省与 ρ 成正比；但 ρ 只描述 QK^T 与 PV 的乘加量，不描述掩码索引本身的访存。若采用稠密偏置方案，ρ 不带来任何算力节省，只增加一次 N×N 的掩码加法与一份 N×N 的偏置显存——这是本方法在长文本版面下的主要代价来源。以 N=8192、FP16 偏置为例，单层单头一份掩码偏置即 128 MiB 量级，多层多头叠加后显存峰值迅速超过潜变量激活本身；因此掩码必须以布尔位图或块索引表形式压缩存储，并在 kernel 内即时展开。</p>\n<p>调度器输出的掩码温度 σ(λ(t)/τ) 决定块间泄漏比例，泄漏意味着掩码不再是严格块对角，而是“块对角 + 按比例放开的块间对”。这使稀疏度 ρ 随采样步变化：早期步 ρ 接近 1（近似全局注意力），后期步 ρ 趋近块对角值。kernel 必须支持每步重建掩码结构，或预先按步生成一串掩码并按步索引。后者把掩码构造移出采样热路径，代价是显存中同时驻留 T 份掩码描述符；前者把构造开销摊到每步，在 CPU 侧成为并发瓶颈。工程判断是：步数少、块数少时预生成；步数多、块数多时按步惰性构造并缓存最近若干步。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-15\">十五 · 数据类型选择：FP16/BF16、FP8 与 NVFP4 在掩码注意力中的分工</h3>\n<p>掩码注意力各阶段的数值敏感度并不相同。QK^T 的 logits 决定 softmax 分布，对量化误差最敏感；PV 的输出直接进入残差流，误差会被后续层放大；QKV 投影是标准 GEMM，可用低精度张量核心。Blackwell 第五代 Tensor Core 对 FP8（E4M3/E5M2）与 NVFP4（E2M1，带块级缩放）提供原生 MMA 支持，使“投影与 PV 走低精度、QK^T 保留较高精度”成为可行分工。</p>\n<p>NVFP4 的关键在于块级缩放：每 16 个元素共享一个 FP8 缩放因子，尾数仅 2 位。对注意力权重而言，softmax 输出天然落在 [0,1] 且行和为 1，动态范围窄，适合 NVFP4；但字形 token 的注意力权重分布高度尖锐（少数笔画 token 占据大部分权重），2 位尾数会把 0.9 与 0.95 这类差异抹平，直接表现为笔画边缘的权重抖动。因此 PV 阶段若用 NVFP4，需保证缩放因子按行或按块重新计算，且累加必须在 FP32 中进行。QK^T 阶段建议保留 FP8 甚至 BF16：logits 的动态范围随序列长度增长，E4M3 的 4 位指数在长序列下仍可能溢出，需配合 per-tensor 或 per-row 缩放。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>推荐精度</th><th>累加精度</th><th>主要风险</th></tr></thead><tbody><tr><td>QKV 投影</td><td>FP8 / NVFP4</td><td>FP32</td><td>权重离群值导致缩放失配</td></tr><tr><td>QK^T</td><td>FP8（E4M3）</td><td>FP32</td><td>长序列 logits 溢出</td></tr><tr><td>掩码加法</td><td>布尔/FP32 偏置</td><td>—</td><td>偏置物化的平方级显存</td></tr><tr><td>softmax</td><td>FP32 归约</td><td>FP32</td><td>行最大值与指数精度</td></tr><tr><td>PV</td><td>NVFP4 / FP8</td><td>FP32</td><td>尖锐权重的尾数截断</td></tr></tbody></table>\n<p>掩码本身是布尔结构，不参与量化；但它改变了低精度 kernel 的访存模式。块稀疏跳过使 PV 的 K 维不再是连续长条，而是按块切分的短段，NVFP4 的 16 元素块缩放恰好与这种切分对齐时效率最高；若块 token 数 n_b 不是 16 的整数倍，缩放块会跨越掩码边界，kernel 需做边界处理，实际吞吐下降。这是“掩码稀疏度”与“量化块粒度”之间的耦合代价，选块划分粒度时应尽量让 n_b 对齐 16 或 32。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-16\">十六 · 累加精度与误差传播：从 logits 到字形</h3>\n<p>掩码注意力的误差传播链为：投影量化误差 → QK^T 累加误差 → softmax 分布偏移 → PV 加权误差 → 残差流。其中 softmax 前的 logits 误差被指数放大，是最关键的一环。设真实 logits 为 z、量化后为 z+δ，则注意力权重的相对误差近似为</p>\n<div class=\"formula\">$$\\frac{\\|\\Delta a\\|}{\\|a\\|}\\approx\\|\\delta\\|_{\\infty},\\qquad \\Delta a_i = a_i\\left(e^{\\delta_i-\\delta_{\\max}}-1\\right)$$</div>\n<p>即权重误差由 logits 误差的极值主导，而非均值。这意味着 per-tensor 缩放不足以保护尖锐分布：只要单个 logit 的量化误差偏大，对应 token 的权重就会被显著抬升或压制。字形 token 的权重本就集中，δ 的极值直接决定笔画是否断裂。缓解手段是 QK^T 采用 per-row 缩放并在 FP32 中累加，softmax 的行最大值归约也用 FP32；这两步在 Blackwell 上由 tcgen05 的累加器天然支持，不额外付出吞吐代价。</p>\n<p>累加精度的代价体现在 Tensor Core 的吞吐档位。FP32 累加的 FP8 MMA 与 FP16 累加的 FP8 MMA 在第五代 Tensor Core 上属于不同指令路径，前者吞吐低于后者；若为保住字形质量而全程 FP32 累加，投影与 PV 的低精度收益被部分抵消。工程折中是：QK^T 与 softmax 走 FP32 累加，PV 走 FP16 累加但输入用 NVFP4 并配合块级缩放重算。这样在保持 logits 精度的同时，把占算力大头的 PV 压到最低精度档。</p>\n<p>具体例子：一个含三行文本块的版面，每块约 200 个字形 token，潜变量序列 N≈6000。若 QK^T 用 per-tensor FP8 缩放，块间泄漏比例在早期步为 0.5，则跨块对的 logits 动态范围远大于块内对，单一缩放因子必然在某一侧失配；表现为早期步构图正常但后期步字形边缘出现权重闪烁。改为 per-row 缩放后，每行 query 独立定标，块内尖锐分布与块间宽分布各自获得合适刻度，误差极值被压回可控范围。这一改动不增加 FLOPs，只增加每行的缩放因子读写，属于典型的“精度换带宽”判断。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-17\">十七 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA 对掩码注意力的意义</h3>\n<p>Blackwell 的 tcgen05 指令族把 MMA 的累加器从寄存器文件搬到 Tensor Memory（TMEM），这是一个与共享内存、寄存器并列的独立片上存储层级。对掩码注意力的直接意义是：QK^T 的结果可以直接落在 TMEM 中，由后续的掩码加法与 softmax 就地读取，避免 N×N 中间矩阵在寄存器与共享内存之间的往返。稠密注意力中这一往返是带宽瓶颈；块稀疏注意力中它更关键，因为不可见块被跳过后，可见块的 QK^T 结果更零散，寄存器压力分布不均，TMEM 的集中累加正好吸收这种不均衡。</p>\n<p>2-SM MMA（两个 SM 协同执行一条 MMA）把单条指令的 M 维扩展，适合处理大 N 下的 QK^T。掩码注意力的可见块在序列维上不连续，2-SM 协同要求两个 SM 处理同一输出 tile 的不同分片，若 tile 跨越掩码边界，协同效率下降。因此块划分粒度与 MMA tile 形状需对齐：n_b 应不小于 MMA 的 N 维 tile，否则一个文本块被拆到多条指令中，掩码跳过的收益被指令启动开销吃掉。工程上这是“块划分粒度”与“tile 形状”之间的硬约束，比稀疏度本身更影响实际吞吐。</p>\n<p>第五代 Tensor Core 对 NVFP4 的支持伴随微缩放格式（microscaling），即块级缩放因子与数据同路径送入 MMA。对 PV 阶段而言，这意味着 NVFP4 的缩放重算可以融进 MMA 流水，不必单独一趟 kernel。代价是缩放因子的计算本身有延迟：每 16 元素一次归约，若 n_b 较小、块数较多，缩放开销占比上升。具体例子：块 token 数 64、块数 32 的版面，PV 阶段每块 4 个缩放块，缩放归约的指令数与 MMA 指令数之比明显高于单块长文本场景；此时改用 FP8 反而吞吐更高。这是“低精度不是越低位越好”的典型判断点，取决于块粒度而非模型规模。</p>\n<p>显存与带宽侧，TMEM 的容量限制决定了单次能驻留多少 QK^T 结果。N 较大时无法一次装下整个注意力矩阵，必须分块流式处理；掩码的块对角结构恰好使流式处理天然按块推进，可见块算完即释放 TMEM，不可见块直接跳过。这把“平方级显存”转化为“按块流式”的常量显存，代价是块间泄漏比例高时（早期步）流式调度的复杂度上升，因为跨块对需要跨 TMEM 分段聚合。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-18\">十八 · 稀疏索引的访存代价与 kernel 选型</h3>\n<p>掩码注意力的真实瓶颈往往不在 FLOPs 而在索引。块稀疏 kernel 需要一张“可见块表”，描述哪些 (query_block, key_block) 对需要计算。这张表的规模为 B² 量级，若 B=32 则 1024 项，每项含块起止偏移；调度器每步更新泄漏比例时，表内容随之变化。表的构造在 CPU 侧完成，若与采样循环同步执行，单步时延被 CPU 主导；若异步预生成，则需在 GPU 上驻留 T 份表，显存开销与步数成正比。</p>\n<p>kernel 选型上，三条路径的代价结构不同。稠密 kernel + 偏置掩码：实现最简，算力不省，显存开销为 N² 偏置；适合 N 小、块数少、掩码温度变化平缓的场景。块稀疏 kernel + 索引表：算力按 ρ 节省，索引访存为 B² 量级，适合 N 大、块对角明显、后期步占主导的场景。分段 kernel：按文本块切分序列，每段独立做注意力再拼接，天然无跨块对，但早期步的跨块交互无法表达，需在调度器侧改为“先全局后分段”的两段式前向，代价是早期步多一次全局注意力。</p>\n<p>具体例子：单图含 8 个文本块、总序列 N=12000 的密集版面。稠密偏置方案下单层掩码偏置约 12000²×2 字节 ≈ 288 MiB，多头多层叠加不可行；块稀疏方案下索引表仅 64 项，可见块算力为 ρ≈1/8，但索引表需在每步按泄漏比例重建，CPU 构造时延若为毫秒级，相对单步 DiT 前向的占比不可忽略。此时正确做法是把泄漏比例离散化为若干档，预生成对应索引表并复用，用少量质量损失换掉每步构造开销。这是本方法在工程落地时最容易被忽视的一笔账：稀疏度带来算力节省，索引带来访存与调度开销，两者相抵后的净收益取决于块数与步数的组合，而非单一指标。</p>\n<p>监控项应覆盖掩码稀疏度 ρ、块间泄漏比例、单步注意力 kernel 时延、索引表构造时延与显存峰值。其中 ρ 与泄漏比例是质量侧的先行指标，后三者是吞吐侧的先行指标；当 ρ 下降但单步时延不降时，说明瓶颈已从算力转移到索引访存，继续压低精度不会带来收益。</p>\n\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-19\">十九 · 块对角掩码的算子边界：稀疏索引、精度路径与显存平方项</h3>\n<p>DCText 的掩码在自注意力层落地时，真正的工程矛盾不在布尔矩阵本身，而在它与 Blackwell 张量核心精度路径的耦合方式。掩码是布尔稀疏结构、不参与量化，因此 FP8 或 NVFP4 的缩放因子只作用于 Q/K/V 与输出投影，掩码以加性偏置或索引选择的形式旁路注入。问题在于：tcgen05 MMA 期望的是规整的 K 维分块与对齐的 TMEM 累加布局，而块对角掩码天然产生不规则的可见 key 区间——每个文本块的包围盒映射到潜变量网格后长度不一，块内可见 key 段在序列维上非连续对齐。若用加性 −∞ 偏置实现，计算仍按稠密 MMA 铺满，掩码只省下无效结果的语义、不省 FLOPs；若用块稀疏内核跳过非法块，则需要在 2-SM MMA 的配对 SM 之间重新划分 K 维负载，配对两半的可见块数不等时，TMEM 累加器的写回与跨 SM 归约会出现空转周期。这是该方案在算子层的第一条边界：掩码的稀疏度必须与 MMA 分块粒度同构，否则稀疏只体现为显存开销而非算力节省。</p>\n<p>累加精度决定了这条路径能否安全走低精度。注意力打分矩阵在施加掩码前需完成 Q·Kᵀ 的累加，Blackwell 第五代 Tensor Core 在 FP8 输入下以更高位宽累加，NVFP4 路径则依赖块级缩放把动态范围压进微缩放格式；掩码的 −∞ 偏置若在低精度累加器上以有限大负数近似，会在 softmax 前引入数值污染，尤其在块间泄漏比例非零的早期步——此时掩码温度高、泄漏项权重不小，被泄漏的跨块打分与块内打分混在同一累加器里，缩放因子的块粒度与文本块边界不对齐，误差随序列长度累积。工程判断是：掩码收紧的后期步可以放心走 NVFP4/FP8 快路径，因为块间项趋于零、数值分布集中；早期步的全局构图阶段反而应保留 BF16 打分或至少提高泄漏项的累加位宽，否则构图一致性收益会被量化噪声吃掉。这一非对称精度策略本身就是调度器可以输出的第二个控制量，与掩码温度同源。</p>\n<div class=\"formula\">$$C_{\\text{mask}} \\approx \\frac{N^2}{2}\\,b_{\\text{idx}} + N\\,b_{\\text{sel}},\\qquad N=\\sum_{k=1}^{K}\\left(n_k^{\\text{txt}}+n_k^{\\text{lat}}\\right)$$</div>\n<p>逐项解释：$N$ 是拼接后的注意力序列长度，由 $K$ 个文本块的文本 token 数 $n_k^{\\text{txt}}$ 与所属潜变量 token 数 $n_k^{\\text{lat}}$ 求和；$N^2/2$ 项对应块对角结构下仍需物化的索引/偏置元数据规模，$b_{\\text{idx}}$ 为每元素的索引位宽；$N b_{\\text{sel}}$ 是每行选择向量的开销。该式说明代价随块数与字符长度同步膨胀：多块长文本请求合并成批时序列按最长对齐，$N$ 被放大而有效块对角密度不变，掩码显存与激活显存同时被稀释。系统代价因此落在三处——显存峰值由 $C_{\\text{mask}}$ 与潜变量激活共同决定，单步注意力时延受稀疏索引访存模式支配（不规则 gather 打散合并访存，量化内核的实际吞吐低于稠密路径的标称值），批调度则必须按块数与字符长度分桶，把长文本多块请求单独成批。可行的缓解是把掩码构造与索引预计算移出采样循环、与 DiT 前向解耦，并在序列并行下按文本块切分——块对角结构天然适配按块划分的序列切分，跨块泄漏项作为少量边界通信处理。失效条件很明确：当版面解析给出的包围盒在潜变量网格上错位，掩码的块边界与真实字形区域不重合，后期步收紧后文本 token 只能看到错位的潜变量，字形错位在上游就已注定，注意力算子再精确也无法挽回；此时提高掩码温度、放宽泄漏反而能掩盖错位，形成质量与解析精度的隐性权衡。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>掩码形态</th><th>推荐精度路径</th><th>主要代价</th></tr></thead><tbody><tr><td>早期步（高泄漏）</td><td>近全局、块间项非零</td><td>BF16 打分，慎用 NVFP4</td><td>稠密 MMA，FLOPs 不省</td></tr><tr><td>后期步（趋块对角）</td><td>块稀疏、可见段非对齐</td><td>FP8/NVFP4 + 块稀疏内核</td><td>索引 gather 访存、TMEM 空转</td></tr></tbody></table>\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-20\">二十 · 显存账本的三层结构：权重、激活、掩码</h3>\n<p>在 DCText 这类推理侧注意力改造里，显存不是一笔糊涂账，必须拆成三层分别核算。第一层是 DiT 主干权重，属静态占用，随精度档位线性缩放：BF16 下每参数 2 字节，FP8 下 1 字节，NVFP4 下约 0.5 字节外加分组缩放因子。第二层是每步激活，包括潜变量序列、文本 token 嵌入、QKV 投影中间结果与注意力输出，随批大小与序列长度线性增长。第三层是本方法特有的掩码与稀疏索引，随注意力序列长度平方增长，是账本里唯一按 O(L²) 膨胀的项。</p>\n<p>把三层写成可复算的预算式，设参数总量 P、权重字节宽 b_w、批大小 B、序列长度 L、隐藏维 d、激活字节宽 b_a、掩码每元素字节 b_m、层数 N_l：</p>\n<div class=\"formula\">$$W = P \\cdot b_w,\\quad A \\approx B \\cdot L \\cdot d \\cdot b_a \\cdot k_a,\\quad M \\approx N_l \\cdot B \\cdot L^2 \\cdot b_m$$</div>\n<p>其中 k_a 是激活峰值系数，涵盖 QKV、注意力分数矩阵与 FFN 中间层同时驻留的倍数。峰值显存近似为 W + max_t(A_t + M_t) + 碎片余量。关键判断：当 L 从千级升到数千级，M 项会迅速超过 A 项，成为单卡容量的决定因素。这就是为什么多块长文本请求必须按块数与字符长度分桶，而不能按最长请求对齐合并成批——对齐会把所有请求的 L 抬到最大值，M 按平方放大，整批的显存账本被一条长请求绑架。</p>\n<p>具体例子：一张含四个文本块、每块数十字符的版面，映射到潜变量网格后注意力序列长度可达数千 token；此时若掩码以稠密布尔矩阵存储，单层单请求的掩码占用即达数 MB 量级，乘以层数与批大小后与权重同量级。工程上的直接对策是只存块对角稀疏索引而非全矩阵，把 M 从 O(L²) 压回 O(L·k)（k 为每 token 可见块内 token 数上限）。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-21\">二十一 · 分页与复用：把掩码从平方级拉回线性级</h3>\n<p>分页思路在这里不是 KV cache 的专利。掩码的块对角结构天然可分页：以文本块为单位分配页，页内记录该块在潜变量网格上的包围盒范围与 token 区间，注意力内核按页遍历可见 key 区间，而不是遍历整条序列再查表。这样每步只需按调度温度调整块间泄漏页的开关比例，页表本身在采样循环内不变，可与采样步解耦预计算——这正是材料中“掩码构造与采样循环解耦”的落地方式。</p>\n<p>复用则体现在两个层面。其一是跨步复用：掩码的块划分由版面解析一次得出，整个采样轨迹上不变，变的只是泄漏比例 λ(t)/τ 经 sigmoid 后的标量权重，因此页表与包围盒映射只算一次。其二是跨请求复用：同一版面模板的多个请求共享页表结构，仅 token 嵌入不同。伪代码思路如下：</p>\n<ul>\n<li>解析版面 → 块包围盒 → 映射到潜变量网格 → 生成块页表（一次）</li>\n<li>每步：由 t 与 T 算温度 → 取 sigmoid 标量 → 按比例开启块间泄漏页 → 内核按页遍历可见区间</li>\n<li>后期步泄漏趋零，页表退化为纯块对角，内核走最紧的稀疏路径</li>\n</ul>\n<p>代价要算清楚：分页把显存从平方级降到线性级，但引入间接寻址，注意力内核的访存模式从连续变为按页跳转，实际吞吐受页大小与块数影响。块数多、每块 token 少时页碎片化严重，索引开销上升；块数少、每块 token 多时页内连续性好但块对角收益下降。这是一个需要按版面统计调参的工程折中，而非免费午餐。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-22\">二十二 · 压缩：布尔掩码不量化，但索引可以压</h3>\n<p>材料明确掩码为布尔稀疏结构、不参与量化，注意力算子可沿用 FP8 或 NVFP4 路径。这句话的工程含义是：量化省下的是权重与激活的字节，省不下掩码的字节。因此压缩的重点不在掩码数值精度，而在索引表示。位图压缩是首选：把每行 token 的可见性压成位串，块对角结构下位串高度规律，游程编码可把页表压到接近块数级别。次选是块稀疏格式，只存可见块的起止偏移。</p>\n<p>另一条压缩路径是序列侧。文本 token 与潜变量 token 拼接成一条注意力序列，文本 token 数量随字符数增长。若把每块文本 token 池化为固定长度的块摘要向量，序列长度 L 下降，M 按平方受益，这是比压索引更根本的杠杆。代价是字形细节信息损失，与后期步锐化目标冲突，需在块摘要维度上做取舍。</p>\n<p>带宽瓶颈的位置要指清楚：权重读取在解码阶段是流式的，受 HBM 带宽约束；注意力分数矩阵的读写受片上与 HBM 之间往返约束；掩码索引的读取量小但随机，落在 L2 与 HBM 的混合路径上。真正卡住吞吐的往往不是掩码本身的字节数，而是稀疏索引导致的非连续访存把有效带宽打下来——同样的 HBM3e 带宽，连续访问能跑满，按页跳转只能跑出折扣后的有效值。因此掩码内核的优化目标应是提高页内连续性、减少页间跳转次数，而不是单纯减小索引体积。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-23\">二十三 · 卸载与容量档位：HBM3e 怎么算</h3>\n<p>容量核算按“权重常驻 + 激活峰值 + 掩码峰值 + 碎片余量”四块相加，再留出框架与通信缓冲。以单卡为例，权重项由参数总量与精度档位直接乘出；激活项按批大小、序列长度、隐藏维与峰值系数估；掩码项按层数、批大小、序列长度平方与每元素字节估。三档精度下权重的比例关系是 2 : 1 : 0.5，而掩码项与精度无关，因此低精度档位下掩码在总账中的占比反而上升——这是量化部署时容易被忽视的账本结构变化。</p>\n<p>卸载策略分两类。第一类是把掩码页表放到主机侧，按步预取到设备，适合块数多但每步只需少量泄漏页的场景，代价是每步一次小传输的固定延迟。第二类是把不参与当前步的块潜变量分片暂存，等该块进入收紧阶段再换入，适合多块版面下块间计算错峰的情形。两类卸载都以 PCIe 或 NVLink 传输换显存，是否划算取决于单步 DiT 前向时间与传输时间的比值：前向越长，卸载越容易被掩盖。</p>\n<p>容量档位的选择逻辑：先按最坏请求（最多块数、最长字符）算 M 峰值，再按批调度分桶后的典型请求算 A 峰值，两者取大加上权重，得到单卡下限。若下限超过单卡容量，优先降批大小而非降精度——因为掩码项不吃精度，降精度只削权重项，对平方级掩码无效。具体例子：四块长文本请求单独成批时，掩码峰值可能已接近权重占用；此时把批拆成两块一组，M 按批线性下降，比换低精度档位更能解容量问题。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-24\">二十四 · 可复算的显存预算与调度耦合</h3>\n<p>给出一份可复算的预算模板，读者代入自己模型的参数即可。设 P = 模型参数量，b_w 取 2 / 1 / 0.5 字节对应 BF16 / FP8 / NVFP4；B 为批大小，L 为注意力序列长度，d 为隐藏维，b_a 取 2 或 1，k_a 取 3 至 5 覆盖 QKV 与 FFN 峰值；N_l 为层数，b_m 取位图压缩后的等效字节。代入后得到三项，相加乘 1.2 的碎片与框架余量，即为单卡显存需求。</p>\n<div class=\"formula\">$$\\text{Peak} \\approx 1.2 \\times \\left(P b_w + B L d b_a k_a + N_l B L^2 b_m\\right)$$</div>\n<p>用这个式子做敏感性分析：L 翻倍，激活项翻倍、掩码项四倍；B 翻倍，两项都翻倍；精度从 BF16 降到 FP8，只有第一项减半。结论很直接——在长文本多块场景，控制 L 与 B 的乘积比控制精度更能压住峰值，而控制 L 本身（块摘要、分桶、单请求成批）是唯一能压住平方项的手段。</p>\n<p>预算与调度的耦合点在于分桶策略。按块数与字符长度分桶，使同批请求的 L 接近，避免对齐放大；对超长请求单独成批，牺牲批效率换显存安全；把掩码页表预计算移出采样循环，用主机侧内存换设备侧峰值。监控项应落在掩码稀疏度、块间泄漏比例、单步注意力时延与显存峰值四条曲线上，其中显存峰值随采样步变化——早期步泄漏页多、索引活跃，后期步页表收紧，峰值往往出现在中段而非首步，这一点在容量规划时容易算错。</p>\n<p>最后落到一个工程判断：DCText 的显存代价不是掩码矩阵本身，而是“平方级结构 + 稀疏访存”这一组合在长文本版面下的叠加效应。把掩码从稠密矩阵改为按块分页的位图索引，把页表构造移出采样循环，把批按块数与字符长度分桶，这三步做完，掩码项从决定容量的主项降为与激活同量级的次项；剩下的带宽瓶颈转移到注意力内核的页内连续性上，那才是下一步该动的地方。</p>\n\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-25\">二十五 · 掩码矩阵的显存账本与批调度边界</h3>\n<p>DCText 的显存代价不在权重，也不在 KV cache——扩散采样没有自回归 KV 复用，潜变量序列与掩码矩阵才是账本主体。设注意力序列长度为 <i>L</i>（图像潜变量 token 加各文本块 token），块数为 <i>B</i>，则布尔掩码规模为 <i>L</i><sup>2</sup> 位；若以字节对齐的稀疏索引存储，每行还需记录可见区间起止，索引开销随 <i>B</i> 线性增长而随 <i>L</i> 线性铺开。可复算的预算式：单请求掩码显存 ≈ <i>L</i><sup>2</sup>/8 字节（位图）+ <i>L·B</i>·8 字节（区间索引），再乘采样步数缓存份数（若逐步预生成）或单份复用（若步内即时构造）。以 <i>L</i>=8192、<i>B</i>=8 为例，位图约 8 MB、索引约 0.5 MB，单份尚可；但若把 16 个多块长文本请求按最长序列对齐合批，<i>L</i> 抬到 16384，位图即升至 32 MB/请求，激活与注意力工作区同步放大，批大小被迫压缩，吞吐收益被显存墙吃掉。</p>\n<p>带宽瓶颈的位置由此确定：掩码本身是布尔结构、不参与 FP8/NVFP4 量化，但它决定了注意力内核的访存模式。块对角稀疏意味着每个 query 行只触及所属块的 key 区间，理想情况下 HBM 流量按 <i>B</i> 分之一收缩；然而稀疏索引的间接寻址使内核难以维持 tcgen05 路径上的连续大块搬运，实际吞吐取决于索引是否被压成规则的分段区间。工程判断是：把掩码构造与采样循环解耦，在请求进入时按版面解析结果预计算分段区间表并常驻，步内只按温度阈值切换泄漏比例，避免每步重扫 <i>L</i><sup>2</sup> 位图。</p>\n<p>失效条件集中在两处。其一，批调度若按块数与字符长度分桶失败，长请求对齐会同时放大掩码与激活，此时质量收益被平方级显存开销抵消，属于典型的“免费增益”误判。其二，包围盒映射到潜变量网格的误差是上游失败模式：掩码收紧后文本 token 只看到错位区域，笔画直接错位，注意力层无法自救。因此该方案的适用边界是块数适中、版面解析可信、批内序列长度方差可控的负载；跨块语义一致性在后期步收紧后是否退化，材料未给出量化边界，只能作为监控项而非承诺。</p>\n<table class=\"mini\"><thead><tr><th>项</th><th>随规模变化</th><th>系统代价</th></tr></thead><tbody><tr><td>掩码位图</td><td><i>L</i><sup>2</sup>/8 字节</td><td>显存峰值、批大小上限</td></tr><tr><td>区间索引</td><td><i>L·B</i>·8 字节</td><td>CPU 侧构造、HBM 间接寻址</td></tr><tr><td>块间泄漏</td><td>由 λ(t) 调度</td><td>早期步近似全局，带宽回升</td></tr></tbody></table>\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-26\">二十六 · 掩码构造从采样循环里剥离：预计算与分桶</h3>\n<p>DCText 的掩码是块对角布尔矩阵，规模随注意力序列长度平方增长。序列长度由文本块数与每块字符数共同决定，而扩散采样每步都要重算注意力，若掩码构造留在步循环内，CPU 侧索引生成会与 GPU 前向串行，单步时延被拉长。工程上正确的做法是把掩码构造与采样循环解耦：请求进入时先做版面解析、块划分与包围盒到潜变量网格的映射，一次性生成整条调度曲线上的掩码序列（或至少生成稀疏索引结构），采样步只做查表与温度插值。这样掩码构造的代价从「每步一次」降为「每请求一次」，与 DiT 前向的 GPU 时间重叠在预填阶段。</p>\n<p>分桶策略直接决定显存峰值。多块长文本请求若合并成批，序列长度按批内最长请求对齐，掩码矩阵与激活显存被放大到最长请求的平方量级，短请求的算力被浪费在填充上。按块数与字符长度分桶，把同量级请求聚成一批，能让掩码矩阵的填充率可控。批大小上限由掩码矩阵显存反推：给定显存预算与单请求掩码字节数，可解出批大小上界。</p>\n<div class=\"formula\">$$B_{\\max}=\\left\\lfloor\\frac{C_{\\text{mask}}}{N_{\\text{req}}\\cdot L_{\\text{seq}}^2\\cdot b_{\\text{bool}}}\\right\\rfloor$$</div>\n<p>其中 $C_{\\text{mask}}$ 为分配给掩码的显存预算，$L_{\\text{seq}}$ 为对齐后序列长度，$b_{\\text{bool}}$ 为布尔元素位宽。这个上界在长文本版面下会迅速收缩，意味着高并发场景必须靠分桶而非增大批大小来提吞吐。代价是调度器要维护多套桶队列，桶间负载不均时出现空闲，尾延迟在桶边界上抖动。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-27\">二十七 · 连续批处理与 chunked prefill 在扩散采样里的变形</h3>\n<p>自回归推理的连续批处理靠 KV cache 的逐 token 追加实现请求进出批；扩散采样没有自回归 KV cache，每一步都是对整幅潜变量的全序列前向，请求的「进度」是采样步而非 token。因此连续批处理在 DCText 上的对应形态是步级批调度：批内请求共享采样步计数，新请求在步边界插入，已完成请求在步边界退出，批组成随步推进而变化。插入点必须对齐到掩码温度曲线的同一相位，否则同一批内不同请求处于不同泄漏比例，注意力内核无法共享同一份掩码结构，只能退化为逐请求掩码，失去批内复用。</p>\n<p>chunked prefill 的类比物是潜变量序列的分块前向。文本块天然是分块单位：块对角掩码使块内注意力与块间泄漏可分离计算，先算块内块对角部分，再按温度加权算块间泄漏部分。这允许把长序列切成块依次送入注意力内核，降低单次前向的激活峰值。伪代码思路如下：</p>\n<ul>\n<li>对每个文本块 $k$，取 query 集合 $Q_k$ 与 key 集合 $K_k$，算块内注意力 $A_k=\\mathrm{softmax}(Q_kK_k^\\top/\\sqrt{d}+M_{\\text{diag}})$；</li>\n<li>按温度 $\\sigma(\\lambda(t)/\\tau)$ 算块间泄漏项，只对相邻块或阅读顺序相邻的块对计算，远距离块对直接置零；</li>\n<li>把块内结果与泄漏项按掩码权重合并，写回整幅注意力输出。</li>\n</ul>\n<p>代价是块间泄漏项的计算量随块对数量增长，若不做邻接剪枝，块数 $K$ 时块对为 $K^2$，与全注意力同阶。工程判断是：泄漏项只保留阅读顺序相邻的块对，把 $K^2$ 降到 $O(K)$，用构图一致性的局部性换算力。这一取舍在密集版面下收益明显，在跨区域语义强关联的版面（如标题与正文呼应）下会损失全局一致性，需要按版面类型配置邻接半径。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-28\">二十八 · 优先级、抢占与尾延迟</h3>\n<p>视觉文本生成的 SLO 以单图端到端时延衡量，采样步数不变，时延由 DiT 前向与 VAE 解码主导，掩码调度只改可见性不改步数。这意味着尾延迟的来源不是计算量波动，而是批组成与掩码构造的排队。优先级调度要按请求的块数与字符长度分级：长文本多块请求的掩码矩阵大、单步前向时间长，若与短请求同批，短请求被长请求的步节奏拖住，尾延迟由批内最慢请求决定。</p>\n<p>抢占在扩散采样里是步边界的中断与重排。被抢占请求的潜变量状态需保存（整幅潜变量加步计数），恢复时从保存步继续，掩码按保存步的温度重建。抢占代价是潜变量的显存往返，一幅潜变量的字节数与分辨率、通道数成正比，频繁抢占会把显存带宽吃满。工程上应限制抢占频率，只在桶间负载严重不均时触发，且优先抢占步数进度靠后的请求（其剩余步数少，恢复后很快完成，对尾延迟贡献小）。</p>\n<p>尾延迟的压制手段可归纳为三条：按块数与字符长度分桶隔离长短请求；批内请求对齐采样步相位以保证掩码结构复用；对进度靠后的请求给高优先级以缩短其在批内的停留。三条都指向同一个代价——调度器状态变多，桶队列与相位对齐表占用主机内存与调度 CPU 时间，高并发下调度本身成为瓶颈。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-29\">二十九 · 分离式预填/解码的映射：版面解析与采样分离</h3>\n<p>分离式预填/解码把计算特征不同的两段放到不同资源池。DCText 的对应切分是版面解析与掩码预计算（CPU 密集、访存密集、无 GPU 张量计算）对采样去噪（GPU 密集）。版面解析输出包围盒与阅读顺序，掩码预计算输出整条调度曲线的稀疏索引，这两段可在 CPU 池上完成并与 GPU 池的采样流水线重叠。分离的收益是 GPU 池不被解析抖动污染：解析质量差的请求在 CPU 侧就被标记，不占用 GPU 批位。</p>\n<p>分离的代价是中间数据的搬运。掩码稀疏索引从 CPU 池传到 GPU 池，传输量与索引条目数成正比，块对角结构下条目数为块内对数加邻接块对数，远小于稠密矩阵，但仍是每请求一次的前置时延。若解析与采样在同一节点，可用 pinned memory 加异步拷贝隐藏；跨节点则要走 NVLink 或网络，前置时延进入端到端时延的关键路径。工程判断是：解析与采样同节点部署，用流水线重叠而非跨节点分离，除非解析池的吞吐成为独立瓶颈。</p>\n<p>分离还改变了失败模式的位置。包围盒映射到潜变量网格的误差在解析阶段产生，分离后该误差在进入 GPU 前就可被检测（如包围盒越界、块重叠），把字形错位的上游失败挡在采样之外。这是分离式架构在 DCText 上的隐性收益，代价是解析池需要维护与 GPU 池一致的网格坐标系定义，坐标系版本不一致会引入新的错位来源。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-30\">三十 · 时延与吞吐的取舍：掩码稀疏度作为调节旋钮</h3>\n<p>掩码温度曲线 $\\lambda(t)=\\lambda_0(1-t/T)$ 决定块间泄漏比例随步衰减。泄漏比例高时注意力近似全局，掩码稀疏度低，注意力内核走稠密路径，算力利用率高但字形锐化不足；泄漏比例低时掩码趋近块对角，稀疏度高，内核走块稀疏路径，算力省但需要稀疏索引访存。吞吐与时延的取舍就落在稀疏度的选择上：稀疏度高则单步算力降、吞吐升，但稀疏索引的访存模式若与量化内核（FP8 或 NVFP4）的 tile 布局不匹配，实际吞吐反而下降。</p>\n<p>量化路径与掩码的交互是工程细节：掩码为布尔结构不参与量化，但注意力算子沿用 FP8 或 NVFP4 时，稀疏索引决定的 tile 跳过会改变量化内核的 tile 粒度。若一个量化 tile 内混有可见与屏蔽的 query–key 对，tile 无法整体跳过，稀疏收益被 tile 粒度吃掉。因此掩码的块划分应与量化 tile 边界对齐，块对角结构按 tile 大小取整，使屏蔽区域落在完整 tile 上。</p>\n<p>具体例子：一个含标题、两行正文、页脚的版面，四个文本块映射到潜变量网格后各占若干 tile。早期步泄漏比例高，四块互相可见，注意力近似全局，构图与光照一致；中期步泄漏比例降到邻接块可见，标题与正文的局部呼应保留；后期步趋近块对角，每块只看到自身潜变量，笔画边缘的注意力占比上升。整条曲线的步数不变，端到端时延不变，变化的是每步注意力的算力分布——这就是 DCText 把质量问题转成调度问题的工程含义：不加快采样，而是把算力从背景纹理挪到字形区域。</p>\n<p>取舍的边界在长文本多块版面：块数增加使块对数量增长，邻接剪枝后的泄漏项仍随块数线性增长，掩码矩阵的平方级显存成为硬约束。此时提高稀疏度省算力，但掩码构造与索引访存的显存开销不降，吞吐被显存带宽卡住而非算力卡住。工程判断是：块数超过阈值后，分桶隔离长请求、限制批大小、把掩码预计算移出关键路径，三件事的优先级高于继续调温度曲线。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-31\">三十一 · 监控项与调度器的可观测性</h3>\n<p>调度器的决策依赖可观测的量：掩码稀疏度、块间泄漏比例、单步注意力时延、显存峰值。稀疏度反映当前步的块对角程度，泄漏比例反映温度曲线的实际相位，二者共同决定注意力内核走稠密还是稀疏路径。单步注意力时延与显存峰值是容量规划的输入：时延的分布形状（而非均值）决定尾延迟，显存峰值决定批大小上界与桶边界。</p>\n<p>监控项要能定位失败模式。掩码稀疏度异常升高而字形质量未改善，说明版面解析的包围盒误差使块划分失真，掩码收紧到了错误的区域；单步时延在后期步突增，说明稀疏索引访存与量化 tile 布局冲突，tile 跳过失效。这两类信号都在注意力层之外产生，监控必须把解析阶段的包围盒统计与采样阶段的掩码统计关联起来，否则调度器只能看到时延数字而看不到原因。</p>\n<p>容量规划的落点是批大小与桶边界的联合整定：给定显存预算与 SLO 时延上限，用掩码矩阵显存反推批大小上界，用单步时延分布反推桶内请求数上限，两者取小。整定的代价是调度器参数随版面类型分布漂移而失效，需要按请求的块数与字符长度分布定期重算桶边界——这是 DCText 部署里持续存在的运维开销，也是掩码平方级显存代价在调度层的直接投影。</p>\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-32\">三十二 · 从单卡掩码到多卡切分：DCText 的并行边界在哪</h3>\n<p>DCText 的改动落在 DiT 自注意力层：掩码是块对角布尔矩阵，块间泄漏比例由采样步温度控制。这个结构决定了它的并行切分不是“把整幅潜变量均匀摊到 N 张卡”那么简单——切分维度必须与文本块边界对齐，否则一个文本块的 query 和它所属区域的 key 会落在不同设备上，掩码的块对角性被通信打碎。工程上先问一个问题：这条推理链路里，哪些张量是真正需要跨卡同步的？答案集中在自注意力算子的 Q/K/V 投影输出与注意力输出投影之间，其余部分（文本编码、VAE 解码、掩码构造）都是可独立放置的。</p>\n<p>把四种切分放到 DCText 的采样循环里看：TP（张量并行）切的是注意力头维与 FFN 中间维，每层注意力后需要一次 All-Reduce 把部分和归并；EP（专家并行）在纯 DiT 主干上通常不适用，除非主干含 MoE 层，此时 All-to-All 成为主导通信；PP（流水并行）按层切分，跨 stage 只传激活，通信量随 micro-batch 线性增长但频次低；DP（数据并行）复制权重、切分请求，只在权重更新时需要同步，推理侧几乎零通信。DCText 的掩码是逐请求、逐步生成的，天然属于 DP 维度的私有状态，不应跨卡广播。</p>\n<p>代价判断：TP 的 All-Reduce 量与隐藏维度和层数成正比，在 NVLink 5 域内单次 All-Reduce 的时延可被计算掩盖，但当序列长度因多块长文本膨胀、单层注意力计算时间上升时，TP 的通信占比反而下降——瓶颈从通信转到掩码索引的访存。反过来，PP 在低延迟单图生成场景下会引入流水气泡，stage 数越多、micro-batch 越少，气泡占比越高。具体例子：一个含 6 个文本块、每块 40 字符的版面，注意力序列长度远大于单块场景，若用 TP=8 切头维，每层两次 All-Reduce 的固定时延在后期步（掩码趋近块对角、注意力计算变稀疏）时占比上升，此时把块按 DP 分到不同副本、每副本内只处理本块掩码，比继续加 TP 更划算。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-33\">三十三 · NVLink 5 与 NVSwitch：域内带宽决定了哪种切分可行</h3>\n<p>Blackwell 的 GB200/GB300 NVL72 机柜内，GPU 之间通过 NVLink 5 与 NVSwitch 构成全互联域，域内 All-Reduce 与 All-to-All 不必经过 InfiniBand。这条事实直接约束切分选择：TP 与 EP 是通信密集型切分，必须留在 NVLink 域内；PP 与 DP 可以跨节点，因为它们的通信频次低、可被计算掩盖。DCText 的掩码构造若放在 CPU 侧预计算再分发，走的是 PCIe 或主机网络，这条路径的带宽远低于 NVLink，因此掩码应在生成请求的副本本地构造，而不是集中构造后广播。</p>\n<p>用公式刻画通信是否被掩盖：设单层注意力计算时间为 <span class=\"formula-inline\">T_comp</span>，一次 All-Reduce 传输量为 <span class=\"formula-inline\">2(N-1)/N · S · H · b</span>（S 为序列长度、H 为隐藏维、b 为字节数），有效带宽为 B，则通信时间 <span class=\"formula-inline\">T_comm = 2(N-1)/N · S · H · b / B</span>。当 <span class=\"formula-inline\">T_comm &lt; T_comp</span> 时 TP 可被掩盖。DCText 的特殊之处在于 S 包含文本 token 与潜变量 token，多块版面下 S 显著增大，T_comm 线性上升；而掩码稀疏化后 T_comp 的有效计算量下降（非法 query–key 对被跳过），两者反向变化，掩盖条件更容易被打破。这就是“通信什么时候成为瓶颈”的第一个判据：序列膨胀叠加掩码稀疏化。</p>\n<p>具体例子：NVL72 域内做 TP=8 的 All-Reduce，若隐藏维与序列长度使得单次传输量落在几十 MB 量级，NVLink 5 的域内带宽可在微秒级完成，相对单层计算可忽略；但若把同一模型切成 PP=8 跨两个节点，stage 间激活传输走 InfiniBand，单次时延上升一个量级，低并发单图请求的端到端时延被流水气泡与跨节点传输共同拉长。工程判断：DCText 这类单图、低并发的推理形态，优先把并行度压在 NVLink 域内，用 TP 或块级 DP，避免跨节点 PP。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-34\">三十四 · All-to-All 与 All-Reduce 的代价结构不同</h3>\n<p>All-Reduce 是归约型通信，所有 rank 的贡献被求和后广播，通信量与模型参数量或激活量成正比，适合 TP 的层内部分和归并。All-to-All 是交换型通信，每个 rank 向其他所有 rank 发送不同的数据分片，适合 EP 的 token 路由与序列并行中的块交换。DCText 的块对角掩码在序列并行下会诱发一种特殊的 All-to-All：若把不同文本块分到不同 rank，块内注意力只需本地计算，但块间泄漏（早期步温度高时）要求跨 rank 可见，此时需要按泄漏比例做部分 key 的交换，交换量随泄漏比例上升。</p>\n<div class=\"formula\">$$V_{\\text{exchange}} \\propto \\sum_{b}\\left(1-\\sigma\\left(\\frac{\\lambda(t)}{\\tau}\\right)\\right)\\cdot S_b\\cdot H\\cdot b$$</div>\n<p>这个式子说明：早期步泄漏大，跨块交换量高；后期步泄漏趋近零，交换量趋近零。于是通信负载在采样轨迹上是非平稳的——前几步通信重、后几步通信轻。调度器若按固定并行策略跑完整条轨迹，前期会成为通信瓶颈，后期则浪费带宽。更合理的做法是让掩码温度曲线与并行策略联动：高温段用更粗的块分组减少跨 rank 交换，低温段收紧到块内、允许更细的切分。代价是调度复杂度上升，收益是通信峰值被削平。</p>\n<p>具体例子：一个 4 块版面在 4 卡序列并行下，早期步若泄漏比例为中等，每块需向其余 3 卡交换部分 key，All-to-All 的传输量约为块内 key 量的数倍；到后期步泄漏趋零，交换量降到接近零，此时若仍维持 4 卡切分，卡间负载不均（每卡只算本块）反而造成计算空转。这说明 DCText 的并行策略不应是静态的，而应随掩码调度阶段切换——这是它与常规 DiT 推理并行最大的不同点。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-35\">三十五 · NIXL 传输：把掩码与潜变量放在正确的存储层</h3>\n<p>NIXL 面向的是推理系统中的点对点数据传输，典型用途是分离式预填/解码之间的 KV 与激活搬运、多副本间的权重与缓存共享。对 DCText 而言，扩散采样没有自回归 KV cache，NIXL 的用武之地在两个地方：其一是把预计算的掩码矩阵从 CPU 内存或远端存储搬到 GPU 显存，其二是多副本 DP 场景下共享版面解析结果与文本编码输出。掩码矩阵随序列长度平方增长，是显存占用的主要项之一，若每个副本各自构造，CPU 侧重复计算与显存重复占用同时发生；用 NIXL 做一次构造、多副本拉取，可把构造开销摊薄。</p>\n<p>但搬运本身有代价：掩码是布尔稀疏结构，传输的是索引与位图，字节数小于稠密浮点矩阵，然而 NIXL 传输的时延与带宽取决于链路——域内走 NVLink 快，跨节点走网络慢。若掩码在采样循环内逐步生成（温度随步变化），则每步都可能需要新掩码，传输频次上升。工程上应把掩码构造与采样循环解耦：按总步数与温度曲线一次性预生成整条轨迹的掩码序列，再按步索引取用，把 NIXL 传输从每步一次降为每请求一次。代价是显存中同时驻留多步掩码，序列长时显存峰值上升，需要在“传输频次”与“显存驻留”之间做权衡。</p>\n<p>具体例子：多块长文本请求在 DP 副本间共享文本编码输出，文本编码器只跑一次，编码结果经 NIXL 分发到各副本，避免每副本重复编码。若文本编码分支与 DiT 主干在同一 GPU 上，这一步省下的是编码算力；若编码器单独部署，NIXL 传输的是嵌入张量，量级远小于掩码矩阵，收益主要在算力而非带宽。判断依据是：文本编码算力占比高则共享编码划算，掩码显存占比高则共享掩码划算，两者不应混为一谈。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-36\">三十六 · 通信成为瓶颈的三个判据</h3>\n<p>第一个判据是序列膨胀比。DCText 的注意力序列由潜变量 token 与各文本块 token 拼接而成，块数与字符数增加时 S 上升，TP 的 All-Reduce 量与序列并行下的 All-to-All 交换量都随 S 线性增长，而单卡计算量在掩码稀疏化后不一定同比例增长。当 S 的增长快于有效计算量的增长，通信占比上升。第二个判据是掩码稀疏度。稀疏度越高，非法 query–key 对被跳过，单层计算时间下降，掩盖通信所需的计算窗口变窄，原本被掩盖的 All-Reduce 时延暴露出来。第三个判据是并发批大小。多块长文本请求合并成批时序列按最长请求对齐，掩码矩阵与激活显存被放大，批内计算时间上升但通信量也随批内 token 总数上升；当批大小受掩码显存限制而无法继续增大时，通信与计算的比例趋于固定，此时增加并行度不再提升吞吐，只会增加通信开销。</p>\n<p>用伪代码表达调度判断：</p>\n<div class=\"formula\">$$\\text{if } \\frac{T_{\\text{comm}}(S, N)}{T_{\\text{comp}}(S, \\text{sparsity})} &gt; \\theta \\text{ then reduce } N \\text{ or switch to block-level DP}$$</div>\n<p>其中 θ 是工程上设定的容忍比例，N 是切分度。这个判断应在请求进入时按块数与字符长度预估，而不是等运行时监控报警。具体例子：一个 8 块、每块 60 字符的版面，S 远大于单块短文本请求，若沿用单块场景的 TP=8，All-Reduce 时延在后期步稀疏注意力下不再被掩盖，端到端时延上升；此时改为按块分 DP、每副本内 TP=2，通信量下降、显存按副本分摊，单图时延反而更稳。代价是副本数增加带来权重复制显存开销，需要在显存容量档内做取舍。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-37\">三十七 · 并行拓扑与掩码调度的联动设计</h3>\n<p>把上述判据落到部署形态：DCText 的掩码是逐请求私有状态，块划分由版面解析决定，因此最自然的并行轴是“按块分 DP”——每个副本处理一个或一组文本块，块内注意力本地完成，块间泄漏通过 NIXL 或 NVLink 做小规模交换。TP 留在副本内切头维，切分度按单块序列长度选择，避免跨块通信。PP 只在模型层数多、单卡显存放不下主干时启用，且应把 stage 边界放在注意力层之外，减少跨 stage 的掩码相关张量传输。这套拓扑的通信峰值出现在早期步（泄漏大、交换多），调度器可在高温段临时合并块分组、降低切分度，在低温段恢复细切分。</p>\n<p>监控项应覆盖：掩码稀疏度、块间泄漏比例、单步注意力时延、All-Reduce/All-to-All 传输量、显存峰值。其中泄漏比例与传输量是联动指标——泄漏比例上升必然带动跨 rank 交换量上升，若监控显示传输量上升而单步时延未同步上升，说明通信仍被掩盖；若时延同步上升，则已越过瓶颈判据。工程判断落在具体机制上：DCText 的并行设计不是选一个静态切分度，而是让切分度跟随掩码温度曲线走，把通信负载在采样轨迹上削峰填谷；做不到这一点时，宁可降低并行度、把块留在单卡内，也不要让块对角掩码被跨卡通信打碎。</p>\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-38\">三十八 · 精度塌陷：从字形断裂到跨块语义漂移</h3>\n<p>DCText 的精度塌陷不是数值溢出意义上的崩坏，而是注意力可见性被错误约束后产生的结构性退化。掩码公式 <span class=\"formula\">$$M_{ij}(t)=\\sigma\\left(\\frac{\\lambda(t)}{\\tau}\\right)\\cdot\\mathbb{1}\\left[\\mathrm{block}(i)=\\mathrm{block}(j)\\right]+\\left(1-\\sigma\\left(\\frac{\\lambda(t)}{\\tau}\\right)\\right)\\cdot\\mathbb{1}\\left[\\mathrm{block}(i)\\neq\\mathrm{block}(j)\\right]$$</span> 里，<span class=\"formula\">$$\\lambda(t)=\\lambda_{0}\\left(1-\\frac{t}{T}\\right)$$</span> 是唯一的时间自变量。当 <span class=\"formula\">$$\\lambda_{0}$$</span> 取大、或温度 <span class=\"formula\">$$\\tau$$</span> 取小，后期步的块间泄漏比例趋近于零，文本 token 只能看到本块潜变量，笔画锐化成立，但跨块的光照、透视与材质一致性失去约束——表现为同一版面内两块文字明暗方向不一致、字重跳变。反过来，<span class=\"formula\">$$\\lambda_{0}$$</span> 偏小则后期步仍保留可观泄漏，背景纹理继续与字形 token 竞争注意力权重，笔画边缘被稀释，回到论文要解决的原始问题。诊断上应把「块内注意力占比」与「块间泄漏比例」作为两个独立观测量：前者低说明字形锐化不足，后者高说明构图约束过强。工程上更隐蔽的一类塌陷是掩码施加层位置错误——若掩码只加在部分自注意力层，未加层的全局注意力仍会把背景 token 混入，视觉上呈现为局部笔画清晰、整体版面发虚的混合态，单看 PSNR 类指标无法区分，必须按层记录掩码命中率。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-39\">三十九 · OOM 与批抖动：平方级掩码矩阵的真实代价</h3>\n<p>显存峰值的第一来源不是潜变量序列，而是掩码矩阵。掩码规模随注意力序列长度平方增长，序列长度又由文本块数与每块字符数共同决定，因此同一批内「三块短文本」与「一块长文本」的显存占用可以相差一个量级。若按常规连续批处理把多块长文本请求合并，序列按最长请求对齐，掩码矩阵与激活显存被同步放大，OOM 往往在采样中段才触发——此时版面解析、文本编码、前若干步 DiT 前向都已付出算力，属于典型的「算完再死」。批抖动的机制是分桶粒度与请求分布不匹配：按块数分桶而忽略字符长度，会让桶内最长序列反复拉高对齐长度，吞吐在桶间来回震荡。可操作的做法是把分桶键设为（块数，字符长度分位），并对掩码采用块稀疏表示而非稠密布尔矩阵，只存块对角块与泄漏索引，把平方项压回线性项。代价要如实计入：稀疏索引本身带来额外访存，若注意力内核仍按稠密 tile 调度，索引查表会打断 MMA 流水，实际吞吐可能低于稠密小矩阵路径。监控项应包含单步显存峰值、掩码矩阵字节数占序列激活的比例、以及桶内序列长度方差。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-40\">四十 · 尾延迟：掩码构造与采样循环的耦合</h3>\n<p>端到端时延由 DiT 前向与 VAE 解码主导，掩码调度不改变采样步数，因此平均延迟对掩码不敏感——但尾延迟敏感。原因是掩码构造依赖版面解析输出，解析在 CPU 侧完成，块数多、包围盒重叠、阅读顺序歧义时解析耗时上冲；若掩码构造与采样步循环串行耦合，第 t 步必须等第 t 步的掩码温度算完才能发射注意力内核，CPU 抖动直接传导为 GPU 空转。并发上升时这一路径成为瓶颈，P99 被解析长尾拉高，而 P50 几乎不动，形成典型的尾延迟放大。解法是把掩码构造与采样循环解耦：版面解析后一次性预计算全部步的掩码温度序列与稀疏索引，采样循环只做查表；对块数超过阈值的请求单独成批，避免长尾请求拖累同批短请求。代价是预计算占用额外显存存放多步索引，步数多时这份缓存本身也要计入峰值。定位手段是按请求记录「解析耗时 / 掩码预计算耗时 / 单步注意力时延 / 解码耗时」四段分解，尾延迟上升时看哪一段的方差先扩大。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-41\">四十一 · 静默降级：没有报错的错误输出</h3>\n<p>最危险的一类失败不抛异常。掩码为布尔稀疏结构、不参与量化，注意力算子可沿用 FP8 或 NVFP4 路径，但稀疏索引的访存模式会改变量化内核的实际行为：当索引越界或块对角块未被正确对齐到 tile 边界，内核可能回退到保守路径或对越界位置做零填充，输出仍是合法浮点数，图像仍能解码，只是字形区域出现无法归因的模糊。另一类静默降级来自版面解析：包围盒映射到潜变量网格时的取整误差不会报错，直接表现为字形整体偏移若干像素，端到端看是「文字位置不对」而非「注意力错了」，排查方向容易被误导到 VAE 或文本编码器。防御性监控应包含三项断言式指标：掩码稀疏度与理论块对角占比的偏差、块间泄漏比例随步数的单调性、以及每块文本 token 实际聚合到的潜变量坐标范围与包围盒的一致性。任一指标越界即标记该请求为可疑输出，进入离线复核队列，而不是等用户投诉字形错位。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-42\">四十二 · 回滚路径：把调度器做成可旁路的一层</h3>\n<p>回滚的设计前提是承认掩码调度是推理侧轻量改造、可整体旁路。工程上应把调度器实现为注意力算子外的一层策略对象，输出掩码温度与稀疏索引，注意力内核只接受「掩码或空」两种输入；空掩码即退化为原始全局注意力，精度回到论文要解决的基线水平，但不会产生新的失败模式。回滚触发条件应是可观测的而非人工判断：单步显存峰值超过档位阈值、桶内序列长度方差超过分位阈值、块间泄漏比例单调性被破坏、可疑输出队列增速超过阈值，任一条件命中即对该批或该请求关闭掩码调度并记录现场。代价要提前算清：旁路后长文本多块场景的字形质量回落到基线，SLO 中的质量约束需同步放宽或转为告警；旁路不改变时延结构，因为步数与 DiT 前向不变，回滚是质量换稳定而非性能换稳定。更细的一档回滚是只调 <span class=\"formula\">$$\\lambda_{0}$$</span> 与 <span class=\"formula\">$$\\tau$$</span> 而不旁路，把后期步泄漏比例抬回一个安全下限，保留部分字形收益——这一档需要温度曲线在部署前按块数与字符长度分桶标定，否则回滚本身又变成一次无依据的调参。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-43\">四十三 · 诊断顺序：从上游解析到下游内核</h3>\n<p>定位顺序应固定为上游优先：先查版面解析输出的包围盒与阅读顺序，再查掩码构造的块对角对齐，再查注意力内核的稀疏索引命中，最后才怀疑数值精度。理由是包围盒误差会直接传导为字形错位，且在下游表现为「注意力错了」的假象；而掩码矩阵的平方级显存开销与稀疏索引访存是该方法在长文本版面下的主要工程代价，这两项在监控上应作为常驻指标而非故障时才采集。一个具体例子：某请求三块文本、其中一块字符数远超其余两块，分桶时按块数归入同一桶，序列按最长块对齐，掩码矩阵显存被放大到接近档位上限，采样中段触发 OOM 重试；重试后请求被拆散单独成批，时延上升但成功，监控上表现为该桶 P99 跳变而 P50 平稳。若只看平均延迟会误判为容量充足，实际是分桶键缺少字符长度维度。把分桶键、掩码稀疏度、块间泄漏单调性、四段耗时分解这四项做成请求级标签随日志落盘，失败模式就能从「图像不好看」回溯到具体机制，而不是在注意力层反复试温度。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-44\">四十四 · 掩码调度的失效边界与端到端诊断</h3>\n<p>DCText 的失败模式几乎都源于同一个结构事实：掩码是块对角布尔矩阵，其规模随注意力序列长度平方增长，而块划分的正确性完全外包给版面解析。这两点决定了它不是一条“免费增益”路径。最典型的精度塌陷并非来自注意力算子本身，而是上游包围盒映射到潜变量网格时的量化误差——解析给出的框若偏移一个潜变量格，块对角掩码就会把字形 token 与本应属于邻块的潜变量隔离，后期步收紧后笔画直接错位、断连。这类失败在监控上表现为“掩码稀疏度高但字形区域注意力熵异常低”，即模型对错误区域过度自信。定位手段是把每步的掩码可视化成块归属图，与版面解析结果逐块比对，误差通常在第 0 步就能暴露，而不必等到 VAE 解码。</p>\n<p>显存与批抖动是第二类代价。设序列长度为 <span class=\"inline-math\">N</span>、块数为 <span class=\"inline-math\">B</span>，掩码非零元约 <span class=\"inline-math\">N²/B</span>，但索引与布尔存储仍按稠密形状分配时，峰值显存近似正比于 <span class=\"inline-math\">N²</span>。多块长文本请求若按常规连续批处理合并，序列按最长请求对齐，短请求的掩码矩阵被无谓放大，激活显存随之抬升，表现为批内单请求延迟方差扩大——即批抖动。工程判断是按“块数 × 字符长度”分桶而非按请求数分桶，把长文本多块请求单独成批；掩码构造与稀疏索引预计算移出采样循环，否则 CPU 侧索引生成会成为并发上升时的尾延迟来源。尾延迟的另一来源是后期步：掩码收紧不改变步数，DiT 前向与 VAE 解码仍主导端到端时延，但块对角掩码的稀疏访存模式在 FP8/NVFP4 内核上未必比稠密注意力更快，量化内核的实际吞吐取决于索引访存是否连续。</p>\n<p>最危险的是静默降级：掩码温度调度曲线若配置错误，早期步泄漏比例未按 <span class=\"formula\">$$\\lambda(t)=\\lambda_{0}\\left(1-\\frac{t}{T}\\right)$$</span> 衰减，块间交互在整个轨迹上保持高位，字形锐化阶段名存实亡，输出“看起来正常”但笔画细节被背景纹理稀释——没有报错、没有 OOM，只有质量缓慢下滑。监控项必须包括每步的块间泄漏比例、掩码稀疏度、单步注意力时延与显存峰值四项，并对泄漏比例设硬阈值告警。回滚策略应分层：先回退温度调度曲线到保守配置（早期泄漏更大、后期更早收紧），再回退到按块分组的小批模式，最后关闭掩码走全局注意力基线。由于该方法不改训练配方、VAE 解码端不变，回滚只动采样循环与注意力算子，不涉及权重，可在请求级灰度切换。需要清醒的是，材料未给出温度曲线、泄漏比例与施加层位置的消融数值，这些阈值只能靠线上监控的分布统计来定，而不能假设论文机制自带数值边界。</p>\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-45\">四十五 · 口径先行：这份材料能读出什么、不能读出什么</h3>\n<p>DCText 的可核验材料在评测维度上是残缺的：数据集名称、对比基线、定量结果、消融数值全部缺失，硬件档位、并行拓扑、量化方案、KV 策略也均未给出。这意味着任何“DCText 比某基线快多少、字形准确率提升几个点”的说法都不成立。本部分的任务不是复述这些缺失，而是把“缺失”转化为一套可操作的读数规则：当一篇论文只给出机制而给不出数字时，工程读者应当如何建立自己的口径，以及哪些跨论文的数字在什么条件下才允许放在同一张表里比较。</p>\n<p>先把度量对象钉死。DCText 是单图生成请求，端到端时延由三段构成：版面解析与掩码构造（CPU 侧为主）、DiT 采样的 T 步前向、VAE 解码。扩散采样没有自回归 KV cache，因此不存在 TTFT/TPOT 这类按 token 切分的指标语义——把它们硬套到扩散上会得到无意义的数。对 DCText 真正有意义的指标族是：单图端到端时延（SLO 主体）、单步 DiT 前向时延及其随块数/字符数的漂移、稳态吞吐（图/秒，在给定并发与批策略下）、显存峰值（潜变量序列 + 掩码矩阵 + 激活）、以及掩码稀疏度与块间泄漏比例这两个“质量侧代理指标”。功耗在材料中无任何数据，只能作为容量规划时的机架级约束定性提及，不能给出每图焦耳数。</p>\n<div class=\"formula\">$$\\text{Latency}_{\\text{e2e}} = T_{\\text{parse}} + T_{\\text{mask}} + \\sum_{t=1}^{T} T_{\\text{DiT}}(t, N_{\\text{tok}}, B) + T_{\\text{VAE}}$$</div>\n<p>这个式子的工程价值在于它把“掩码调度是否免费”这件事变成可分解的账：掩码构造项可与采样循环解耦预计算，从而在并发上升时不被 CPU 侧索引构造拖住；而求和项里的 $T_{\\text{DiT}}$ 才是主项，掩码只改变每步注意力的可见性，不改变步数 T，所以端到端时延的量级由 DiT 前向与 VAE 解码决定。一个具体例子：某请求含 4 个文本块、总字符数偏长，注意力序列长度 $N_{\\text{tok}}$ 被拉高，掩码矩阵按 $N_{\\text{tok}}^2$ 增长，此时即便单步注意力因块对角而稀疏，显存峰值仍可能先于时延成为瓶颈——这正是“质量收益被平方级开销抵消”的典型现场。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-46\">四十六 · 硬件档位与 batch：材料空白处的推断边界</h3>\n<p>材料未给硬件档位，因此不能声称该方法“在 B200 上如何”。但可以把硬件选择还原为一个由掩码显存占用驱动的判据：掩码是布尔稀疏结构，规模随序列长度平方增长，部署时按掩码矩阵 + 潜变量序列 + 激活的显存峰值选择 GPU 显存容量档。在 Blackwell 上，这条判据的具体形态是：掩码索引与布尔矩阵占用的是 HBM 容量与带宽，而注意力算子本身可沿用 FP8 或 NVFP4 路径（掩码不参与量化），于是同一张卡上“精度路径”和“掩码开销”是两条独立的账，不能因为切了 FP8 就认为掩码开销消失。</p>\n<p>batch 维度的口径更微妙。多块长文本请求若合并成批，序列长度按最长请求对齐，掩码矩阵与激活显存被同步放大——这不是线性放大，而是按最长序列的平方放大后再乘以批内请求数。因此批调度需按块数与字符长度分桶，而非按请求数简单凑批。一个具体机制：把 8 个短块请求与 1 个 12 块长文本请求混批，对齐后前者的掩码矩阵被无谓放大到后者规模，显存峰值由最长者决定，吞吐反而低于分桶后的两批。工程判断是：DCText 的批策略应按 $\\max(N_{\\text{tok}})$ 与块数二维分桶，长文本多块请求宜单独成批。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>口径定义</th><th>受何影响</th><th>可比性风险</th></tr></thead><tbody><tr><td>单图端到端时延</td><td>请求进入到图像输出</td><td>T、DiT 前向、VAE、掩码构造</td><td>步数不同则不可比</td></tr><tr><td>单步 DiT 时延</td><td>一次前向 wall time</td><td>$N_{\\text{tok}}$、块数、稀疏索引访存</td><td>序列长度未对齐则不可比</td></tr><tr><td>稳态吞吐</td><td>图/秒 @ 给定并发</td><td>分桶策略、显存峰值</td><td>批策略不同则不可比</td></tr><tr><td>显存峰值</td><td>采样循环内最高占用</td><td>$N_{\\text{tok}}^2$ 掩码、激活</td><td>分辨率/块数不同则不可比</td></tr><tr><td>掩码稀疏度</td><td>非零可见对占比</td><td>块划分粒度、泄漏比例</td><td>仅为质量代理，非性能指标</td></tr></tbody></table>\n<p>并发维度的口径要单独拎出来：并发上升时掩码构造与稀疏索引成为 CPU 侧瓶颈，若不做预计算解耦，采样步循环会被串行化拖慢，表现为“GPU 利用率下降但端到端时延上升”的反常组合。这是诊断 DCText 部署是否做对的第一信号。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-47\">四十七 · 数字怎么读：四类不可比提升</h3>\n<p>在没有定量结果的前提下，工程读者迟早会面对“别人家的表”。读表时要先做四类不可比性筛查。第一类是步数不可比：掩码调度只改可见性不改步数，但若一方用了步数蒸馏或一致性模型把 T 压到个位数，端到端时延的差距主要来自采样器而非掩码，把两者放在同一栏比较是错的。材料明确未给出是否使用步数蒸馏，因此任何跨采样器的时延对比都不可采信。</p>\n<p>第二类是序列长度不可比：掩码开销按 $N_{\\text{tok}}^2$ 增长，字符数与块数不同的两个请求，其单步时延差异可能全部来自序列长度而非方法优劣。第三类是分辨率与版面不可比：包围盒映射到潜变量网格的精度随分辨率变化，块划分粒度不同会同时改变掩码稀疏度与字形质量，质量数字与性能数字被同一变量耦合，不能拆开比。第四类是精度路径不可比：掩码不参与量化，但稀疏索引的访存模式会影响 FP8/NVFP4 内核的实际吞吐，同一掩码在不同精度内核上的开销不同，跨精度路径比吞吐是无效比较。</p>\n<div class=\"formula\">$$\\text{Speedup}_{\\text{claimed}} = \\frac{T_{\\text{base}}(T_b, N_b, R_b)}{T_{\\text{new}}(T_n, N_n, R_n)} \\;\\text{仅在}\\; T_b=T_n,\\; N_b=N_n,\\; R_b=R_n \\;\\text{时可比}$$</div>\n<p>一个具体例子：某表声称“端到端时延降低”，但基线用 50 步、新方法用 20 步且未说明是否蒸馏——此时降幅主要来自步数，掩码的贡献无法分离。正确读法是要求作者给出同 T、同 $N_{\\text{tok}}$、同分辨率下的单步 DiT 时延对比，以及掩码稀疏度与泄漏比例的对应曲线；材料未给这些，就只能把结论降级为“机制上可缓解注意力竞争”，不给数值边界。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-48\">四十八 · 质量侧代理指标：稀疏度与泄漏比例怎么当数用</h3>\n<p>既然定量结果缺失，质量侧只能靠机制性代理指标建立口径。掩码温度 $\\lambda(t)=\\lambda_0(1-t/T)$ 随步数线性衰减，经 $\\sigma(\\lambda/\\tau)$ 映射为块间泄漏比例：早期步泄漏大、注意力近似全局，后期步趋近块对角。可监控的量是每步的块间泄漏比例与掩码稀疏度。这两个量不是质量指标本身，而是“调度是否按设计走”的过程指标——若后期步泄漏比例未收敛到接近零，字形锐化阶段就没有真正发生，端到端字形质量的失败可以在注意力层被提前定位，而不必等 VAE 解码后看图。</p>\n<p>代价侧要同时记账：稀疏布尔矩阵带来额外索引与显存开销，块数多、序列长时掩码矩阵规模随 token 数平方增长。一个具体机制是稀疏索引的访存模式——块对角结构在理想情况下可退化为按块切分的连续访存，但若块包围盒在潜变量网格上不规则，索引就变成 gather 型随机访存，实际吞吐低于稀疏度所暗示的理论值。因此“掩码稀疏度 90%”不等于“注意力算力省 90%”，这是读这类数字时最常见的误读。</p>\n<ul><li>过程指标：每步块间泄漏比例、掩码稀疏度、单步注意力时延、显存峰值。</li><li>质量代理：后期步字形区域注意力权重占比（材料未给数值，只能定性）。</li><li>上游指标：版面解析包围盒与潜变量网格的映射误差，它直接传导为字形错位，是端到端失败模式的上游来源。</li></ul>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-49\">四十九 · 消融维度的口径：没有数值时如何设计自己的对照</h3>\n<p>材料未给消融，但可推断的消融维度有四条：掩码温度调度曲线（线性衰减 vs 阶跃 vs 余弦）、块间泄漏比例下限、掩码施加层位置（全部自注意力层 vs 部分层）、块划分粒度。工程读者若要在自己的部署上复现，必须把每条维度固定成可对照的口径：温度曲线决定“构图稳定—字形锐化”两阶段的切换点，泄漏比例下限决定后期步是否真的块对角，施加层位置决定算子改造的侵入面与显存开销分布，块划分粒度同时改变掩码规模与字形质量。</p>\n<p>对照设计的代价约束是：任何一条维度的扫描都会改变 $N_{\\text{tok}}$ 或掩码规模，从而改变显存峰值与单步时延，因此消融必须在固定序列长度与分辨率的条件下做，否则测到的是序列长度效应而非调度效应。一个具体例子：把施加层从“全部层”改为“后段层”，显存峰值下降但早期构图稳定性可能退化，此时若不同时报告构图一致性的定性评估，消融结论就是单边的。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-50\">五十 · 容量规划：把缺失的数字换成可执行的判据</h3>\n<p>在无定量结果时，容量规划只能建立在判据而非数字上。第一条判据是显存档位由掩码峰值决定：按目标版面的最大块数与最大字符数估算 $N_{\\text{tok}}$，掩码矩阵按平方增长，加上潜变量序列与激活，得到单请求显存下界，再乘以目标并发得到卡容量需求。第二条判据是批策略按二维分桶：块数与字符长度各自分桶，避免长短混批导致的对齐放大。第三条判据是掩码构造与采样循环解耦预计算，把 CPU 侧索引构造移出关键路径，使并发上升时 GPU 不被串行化拖慢。</p>\n<p>第四条判据是精度路径与掩码开销分开记账：注意力算子可沿用 FP8 或 NVFP4，掩码为布尔结构不参与量化，但稀疏索引访存会侵蚀量化内核的实际吞吐，因此容量估算不能把“切了低精度”当作掩码开销的抵扣项。第五条判据是上游质量门：版面解析的包围盒误差直接表现为字形错位，端到端失败在上游而非注意力层，容量规划应把解析质量作为独立监控项，而非假设它总是正确。最终落到一个工程判断：DCText 的部署价值取决于块稀疏注意力内核能否把平方级掩码开销压到可接受范围，若内核只能做布尔屏蔽而无块稀疏访存优化，长文本多块版面下的显存与吞吐代价会先于质量收益触顶——此时正确的动作是收紧块划分粒度并分桶限流，而不是继续加大文本条件强度。</p>\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-51\">五十一 · 迁移到非 DiT 主干：掩码挂载点决定改造量</h3>\n<p>DCText 的掩码是挂在 DiT 自注意力层上的 query–key 可见性约束，迁移的第一道门槛不是模型大小，而是主干里有没有一个\"序列化潜变量 + 全局自注意力\"的结构可供切割。UNet 系扩散主干的空间注意力与交叉注意力分离，文本条件走 cross-attention，掩码要落到 self-attention 的潜变量网格上才有意义；若强行把块对角掩码加到 cross-attention，等于把文本 token 与图像 token 的对应关系人为截断，字形约束反而失效。流匹配采样器与扩散采样器在这一点上同构——掩码只依赖采样步 t 与总步数 T 的比值，不依赖具体的噪声调度形式，因此从 DDPM 轨迹迁到 flow matching 轨迹时，调度器只需把 λ(t)=λ₀(1−t/T) 里的 t 重新解释为当前积分步序号，公式形式不变。</p>\n<p>真正的改造量出现在注意力内核侧。掩码以稀疏布尔矩阵参与计算，若主干用的是融合的 FlashAttention 类内核，需要确认该内核是否接受任意布尔掩码；多数高性能内核只原生支持因果掩码或固定窗口，块对角掩码要么退化为稠密掩码乘法（显存按 O(N²) 走），要么需要写一个块稀疏变体。工程判断是：<strong>迁移成本约等于\"写一个块稀疏注意力内核\"的成本，而不是\"加一个 mask 参数\"的成本</strong>。以单图潜变量序列长度 N 为例，掩码矩阵元素数为 N²，若 N 取数千量级、块数取十余块，稠密存储的布尔矩阵在 FP8 注意力路径上会额外占用与激活同量级的显存，直接压缩可用的批大小。</p>\n<div class=\"formula\">$$\\text{mask\\_bytes}=N^2\\cdot b_{\\text{mask}},\\qquad \\text{attn\\_flops}\\propto N^2 d \\cdot \\rho_{\\text{dense}}$$</div>\n<p>其中 ρ_dense 是掩码实际放行比例。块对角结构下 ρ_dense 近似为各块 token 数占比的平方和，块越多、块越小，ρ_dense 越低，理论算力越省；但只有内核真正跳过被屏蔽的 query–key 对，这个节省才兑现，否则省下的只是\"语义上的注意力\"，算力照付。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-52\">五十二 · 迁移到别的生成领域：文本块假设是否成立</h3>\n<p>这套方法的核心假设是\"存在可解析的、空间上互不重叠的文本块，且每块对应一段独立的字形 token 序列\"。迁移到海报、UI 截图、文档渲染这类版面结构化场景，假设成立，掩码的块划分直接来自版面解析的包围盒。迁移到自然图像里的招牌、路牌、包装文字，包围盒仍可解析，但文本块与背景的边界模糊，块内潜变量本身混有大量背景纹理，掩码收紧后字形 token 只能看到一块\"脏\"区域，锐化效果被稀释。迁移到视频逐帧生成，文本块在时间轴上漂移，包围盒需逐帧重算，掩码调度还要叠加时间一致性约束，单帧掩码的块对角结构无法保证跨帧字形稳定。</p>\n<p>更关键的边界在\"文本是否是生成目标\"。若任务只是图像编辑中保留已有文字，掩码应作用于编辑区域而非文本块，块划分逻辑要换成编辑掩码；若任务是文档版面生成且文字由后置渲染管线合成，DCText 的注意力隔离就与渲染管线职责重叠，收益被管线吞掉。判断标准可以写成一个准入条件：<strong>文本 token 必须由模型自身在潜变量空间里逐笔生成，且文本块在潜变量网格上有可分离的空间支撑</strong>，两条同时满足才值得迁移。缺一条，改造注意力的代价换不回字形收益。</p>\n<table class=\"mini\"><thead><tr><th>目标领域</th><th>块可分离性</th><th>主要改造点</th><th>系统代价走向</th></tr></thead><tbody><tr><td>海报/UI/文档</td><td>强</td><td>仅换版面解析器</td><td>掩码显存随块数上升</td></tr><tr><td>自然图像招牌</td><td>弱</td><td>块边界需膨胀、泄漏比例调高</td><td>ρ_dense 上升，算力节省缩水</td></tr><tr><td>视频逐帧</td><td>时变</td><td>逐帧包围盒 + 时间一致性</td><td>掩码构造成为 CPU 侧瓶颈</td></tr><tr><td>编辑保留文字</td><td>不适用</td><td>改用编辑区域掩码</td><td>与文本块调度脱钩</td></tr></tbody></table>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-53\">五十三 · 与其他推理加速手段叠加时的相互作用</h3>\n<p>掩码是布尔结构，不参与量化，因此与 FP8、NVFP4 的权重/激活量化在数值上正交——这是它相对量化类方法的一个结构性优势。但正交不等于无代价：稀疏索引的访存模式会打断量化内核的连续访存假设。量化内核通常按固定 tile 连续读取激活，掩码要求按块边界跳读，索引张量本身要占显存、要走一遍地址计算，实际吞吐可能低于同精度下的稠密内核。工程上应把掩码索引与采样步解耦预计算：版面解析完成后一次性生成各步的掩码索引表，采样循环内只做查表，避免每步重算包围盒映射。</p>\n<p>与批调度叠加时，矛盾更直接。多块长文本请求合并成批，序列长度按最长请求对齐，掩码矩阵与激活显存被同步放大；块数多、字符长的请求会把整批的 N 抬到高位，N² 的掩码开销摊薄了批带来的吞吐收益。可行做法是按块数与字符长度分桶，把长文本多块请求单独成批，短请求走大 batch。与 KV cache 类手段叠加则基本无关——扩散采样没有自回归 KV cache，显存主要由潜变量序列与掩码矩阵占据，这也是它和自回归 LLM 推理优化工具箱交集很小的原因。</p>\n<div class=\"formula\">$$\\text{goodput}\\approx\\frac{B\\cdot \\mathbb{1}[\\text{bucket}(B)\\ \\text{一致}]}{T_{\\text{DiT}}(N_{\\max})+T_{\\text{VAE}}+T_{\\text{mask}}(N_{\\max})}$$</div>\n<p>分母里 T_mask 是掩码构造与索引开销，它与 DiT 前向串行时直接吃端到端时延；解耦预计算后该项可移到请求进入阶段，与采样循环并行，这是迁移到高并发服务时最值得做的一处改动。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-54\">五十四 · 规模上限：平方项与解析精度两条硬边界</h3>\n<p>第一条上限来自 N²。掩码矩阵规模随注意力序列长度平方增长，文本块数与字符数增加时显存与索引开销同步上升。设单块平均 token 数为 n、块数为 k，则 N≈kn，掩码元素数≈k²n²。块数翻倍，掩码开销四倍——这意味着\"多行多词密集版面\"正是该方法最贵、也最需要它的场景，收益与代价同向增长。规模上限的工程判据是：当掩码矩阵显存占用超过单卡可用显存的一个显著比例、进而迫使批大小降到 1 时，吞吐收益被完全吃掉，此时应改用块稀疏内核或按块拆请求串行生成再拼图。</p>\n<p>第二条上限来自版面解析精度。包围盒映射到潜变量网格的误差会直接造成字形错位，失败模式在上游而非注意力层。分辨率越高、潜变量网格越粗，一个网格单元覆盖的像素越多，包围盒量化误差越大；多块紧邻时误差还会让相邻块的掩码互相侵入。这条边界无法靠调掩码温度曲线补救——温度只控制块间泄漏比例，不修正块的位置。判断是：<strong>解析精度决定了该方法的质量天花板，掩码调度只决定它能否接近这个天花板</strong>。若上游解析器在目标版面上召回不足，迁移前应先换解析器，而不是先调 λ₀ 与 τ。</p>\n<ul><li>块数 k 与单块 token 数 n 同时增大时，优先拆请求而非拆块，拆块会让 ρ_dense 下降但索引开销上升。</li><li>掩码施加层位置影响收益：浅层注意力管全局构图，深层管细节，迁移到层数不同的主干时需重新选层，材料未给出该维度的数值边界。</li><li>跨块语义一致性在掩码收紧后可能退化，多块共享同一实体描述时需保留少量块间泄漏，泄漏比例成为质量与一致性的调节旋钮。</li></ul>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-55\">五十五 · 不适用的场景与判断清单</h3>\n<p>三类场景应直接判定不适用。其一，文本由外部渲染管线合成、模型只负责版面布局——注意力隔离与渲染职责重叠，改造无收益。其二，单块短文本、背景简单的图像——注意力竞争本就不严重，掩码的平方开销换不回可测的字形改善，属于\"把掩码调度当作免费增益\"的典型误用。其三，需要跨块强语义一致的长文档生成——掩码收紧到块内会切断块间信息流，字形变锐但版面语义漂移，此时应把泄漏比例下限锁在一个非零值，或改用块间共享的全局 token 作为信息通道。</p>\n<p>迁移决策可以收敛成一张判断清单：主干是否有可切割的全局自注意力序列；文本 token 是否由模型在潜变量空间逐笔生成；版面解析在目标领域的包围盒召回是否足够；注意力内核是否支持块稀疏掩码或愿意承担稠密掩码的显存；请求的块数与字符长度分布是否落在 N² 开销可接受区间。五项里前三项是准入门槛，后两项是成本核算。任何一项不满足，迁移的正确动作是改架构或换方案，而不是调调度曲线。</p>\n<p>最后落在机制上：DCText 的收益本质是把\"字形锐化\"从全局注意力的平均分配中抢回来，抢的方式是在采样轨迹后段人为制造注意力可见性的块对角结构。这个机制的有效半径由两个量界定——掩码放行比例 ρ_dense 决定算力代价，包围盒映射误差决定质量上限。迁移到任何新模型或新领域时，先测这两个量，再决定是否动注意力算子；先动算子再测，等于把平方级显存开销和上游解析误差一起引进服务链路。</p>\n\n<h3 id=\"paper-dctext-scheduled-attention-masking-f-2025-sec-56\">五十六 · 迁移边界：掩码调度在哪些模型与场景上会失效</h3>\n<p>这套方案的可迁移性由三个前提决定：主干必须是带自注意力的 DiT 或流匹配采样器、版面能预先解析为离散文本块、采样步数足够多到能容纳“先松后紧”的两段式调度。迁到自回归语言模型或纯卷积解码器上，掩码语义直接失效——前者没有潜变量网格与文本块包围盒的对应关系，后者的感受野由卷积核而非 query–key 可见性决定。迁到步数极少的蒸馏采样器（4 步、8 步）时，<span class=\"formula\">$$\\lambda(t)=\\lambda_{0}\\left(1-\\frac{t}{T}\\right)$$</span> 在 T 很小时几乎退化为阶跃函数，早期放开与后期收紧挤在同一两步内，构图稳定与字形锐化无法分离，调度收益消失。工程判断是：步数低于十余步的加速采样路径上，应把掩码固定为块对角常量，放弃调度而只保留分治。</p>\n<p>领域迁移的代价集中在版面解析这一上游环节。文档、海报、UI 截图这类块结构清晰的场景可直接复用；自然场景文字（招牌、路牌）的包围盒来自检测模型，误差与遮挡会直接传导为字形错位，此时掩码收紧反而放大错误——因为文本 token 被强制只看向一个错位的潜变量区域。跨块语义一致性是另一处失效点：掩码趋近块对角后，多行段落的行间、词间不再共享上下文，长句断行处的字形风格漂移无法被注意力层纠正。表格给出迁移判断：</p>\n<table class=\"mini\"><thead><tr><th>目标场景</th><th>需改动</th><th>主要代价</th><th>判断</th></tr></thead><tbody><tr><td>同类 DiT 扩散模型</td><td>仅换包围盒映射与层位置</td><td>掩码显存平方增长</td><td>可直接迁移</td></tr><tr><td>少步蒸馏采样器</td><td>去掉调度、固定块对角</td><td>失去两段式收益</td><td>降级使用</td></tr><tr><td>自然场景文字</td><td>换检测器并加误差容限</td><td>解析误差传导为错位</td><td>谨慎，需放宽泄漏</td></tr><tr><td>自回归/卷积主干</td><td>无对应机制</td><td>—</td><td>不适用</td></tr></tbody></table>\n<p>规模上限由掩码矩阵的平方级增长划定。序列长度 L 包含潜变量 token 与各块文本 token，掩码存储与索引开销按 O(L²) 上升；块数 K 增加时，块对角结构变碎，稀疏内核的块尺寸变小、访存效率下降，实际吞吐往往比理论稀疏度更差。批调度必须按块数与字符长度分桶，把多块长文本请求单独成批，否则按最长请求对齐会同时放大掩码与激活显存。与 FP8/NVFP4 量化叠加时要注意：掩码是布尔结构不参与量化，但稀疏索引的访存模式会打断量化内核的连续访存，量化带来的算力节省可能被索引开销部分抵消。最终判断落在一条工程线上——当单图文本块数超过个位数、单块字符数进入长段落量级时，平方级掩码开销会吞掉质量收益，此时应退回全局注意力加文本条件增强，或改用块稀疏内核把可见性约束下沉到硬件支持的稀疏模式里。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">DCText: Scheduled </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Attention Masking for…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · DCText: Scheduled Atten… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>材料未给出对比基线</td></tr><tr><td>主要结果</td><td>材料未给出定量结果；可核验的机制性结论是掩码按步调度可缓解多文本块间的注意…</td></tr><tr><td>消融</td><td>材料未给出消融实验；可推断的消融维度包括掩码温度调度曲线、块间泄漏比例、掩…</td></tr><tr><td>局限</td><td>掩码矩阵随 token 数平方增长，长文本与多块版面下显存与算力开销上升；…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-dctext-scheduled-attention-masking-f-2025 · 共 9 个片段</p>\n";break;}}})();
